quests[24215] = { id = 24215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of the Winds", description = "Look, {name}. The rolling plains of Mulgore stretch before you: our home, the cradle of the Earth Mother. Here she provides us with all we could ever need, a peaceful and verdant land. This is what you will fight to protect.\n\nYour journey will take you far beyond her sheltering arms, to the farthest and cruelest regions of this world, and beyond.\n\nBelow us is Bloodhoof Village. The first step on your true path begins now. Drink deep of the Water of Vision, and let the spirits guide you onward.", sourceObjective = "Drink the Water of Vision.\n\nProvided item:", completion = "Welcome to Bloodhoof Village, hero.  I am glad the spirits have guided you safely here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24216] = { id = 24216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", sourceObjective = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "The Horde is in your debt, {name}.  You've made your people proud with your courage in defending our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[24217] = { id = 24217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", sourceObjective = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "The Horde is in your debt, {name}.  You've made your people proud with your courage in defending our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[24218] = { id = 24218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", sourceObjective = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "Excellent work, {name}.  The integrity of our borders must be preserved at all costs!", sourceObjectiveStatus = "unverified-source-field" }
quests[24219] = { id = 24219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", sourceObjective = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "What news do you bring from the front, {name}?", completion = "Excellent work, {name}.  The integrity of our borders must be preserved at all costs!", sourceObjectiveStatus = "unverified-source-field" }
quests[24220] = { id = 24220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", sourceObjective = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "Excellent news, {class}!  If our tactical deployments continue to be this successful, the Horde will be in full retreat before long.", sourceObjectiveStatus = "unverified-source-field" }
quests[24221] = { id = 24221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", sourceObjective = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "You've brought great honor to the Horde, {name}.  Your victory today will ensure a thousand victories tomorrow!", sourceObjectiveStatus = "unverified-source-field" }
quests[24223] = { id = 24223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", sourceObjective = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "Excellent news, {class}!  If our tactical deployments continue to be this successful, the Horde will be in full retreat before long.", sourceObjectiveStatus = "unverified-source-field" }
quests[24224] = { id = 24224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", sourceObjective = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "Excellent work, {name}.  The integrity of our borders must be preserved at all costs!", sourceObjectiveStatus = "unverified-source-field" }
quests[24225] = { id = 24225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", sourceObjective = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "The Horde is in your debt, {name}.  You've made your people proud with your courage in defending our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[24226] = { id = 24226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", sourceObjective = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24426] = { id = 24426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, {name}.  Earn great honor by heeding the call of the brave Frostwolf warriors.", sourceObjective = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran or Shattrath.", completion = "There is no greater honor than driving invaders from Horde territories.  We salute your great courage in aiding our forces today!", sourceObjectiveStatus = "unverified-source-field" }
quests[24427] = { id = 24427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, {name}, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", sourceObjective = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran or Shattrath.", completion = "Just what I wanted to hear!  A victory in Alterac Valley - even a temporary one - is crucial to our overall strategy against the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[24428] = { id = 24428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Puzzling Circumstance", description = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Zardeth of the Black Claw.", sourceObjective = "Take the Head of Onyxia to Zardeth of the Black Claw in the basement of the Slaughtered Lamb.", progress = "By Nozdormu's teeth!", completion = "What? How did you get this? Isn't she... Never mind the details, I suppose. You'll be wanting one of these baubles as recompense, no doubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24429] = { id = 24429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Puzzling Circumstance", description = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Neeru Fireblade.", sourceObjective = "Take the Head of Onyxia to Neeru Fireblade in the Cleft of Shadow.", progress = "What is the meaning of this?!", completion = "You've brought me the head of someone who is... No, best not to think about it too hard. You'll be wanting recompense for your heroic deeds, no doubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24430] = { id = 24430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacken the Skies", description = "{name}! Give us a hand here, will ya? Gorsch here had a bad experience at the all-you-can-eat seafood joint back in town, and now we're short a pilot.\n\nMy job was to take out those elven glaive throwers before they cut our air units to ribbons. Hop on this wind rider and take to the skies! One of my bombardier buddies will ride with you and bomb the targets at your command.\n\nAnd hey! Chuck a bomb straight at the night elven command center - the large building south of here, beside the bridge. Glorious!", sourceObjective = "Mount a Grounded Wind Rider and fly over Talrendis Point. Destroy 6 Talrendis Glaive Throwers and bomb the Command Center.", progress = "More bombs. More bombs!", completion = "Oh yeah! I love the smell of freshly-cratered dirt!\n\nWord around camp is that the elven front line is collapsing back toward the river. Talk to Chawg and see if there's anything you can do to help seal the deal.", sourceObjectiveStatus = "unverified-source-field" }
quests[24431] = { id = 24431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waterlogged Recipe", description = "This appears to be the remains of a mixture for potent wine.  Perhaps the proprietor of One More Glass in Dalaran would be interested in it....", sourceObjective = "Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city.", progress = "Wine is only as fine as the person drinking it, I always say.", completion = "This is quite a find, {name}.  I can't have you selling this to anyone else, so I'm willing to offer generously.", sourceObjectiveStatus = "unverified-source-field" }
quests[24432] = { id = 24432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Legs", description = "Welcome to The Briny Cutter, {class}.\n\nI am Erunak, the last surviving passenger of this once-proud vessel.\n\nI'm afraid your travails have only just begun. The naga have been attacking here relentlessly.\n\nYou're not equipped to be of much help down here yet, but I can remedy that.\n\nJust outside this ship live a special breed of starfish. Bring me some of them along with a conch shell. I'll prepare an enchantment that should help to increase your chances of survival.", sourceObjective = "Erunak in The Briny Cutter wants you to bring him 3 Saltwater Starfish and a Conch Shell from Seafarer's Tomb.", progress = "It is good to see that you're still alive, {race}.\n\nHave you found the items I require?", completion = "Here you are, {class}. With this you should find maneuvering in the sea to be nearly effortless. \n\nNow we must get to work. There is much to be done in little time.", sourceObjectiveStatus = "unverified-source-field" }
quests[24433] = { id = 24433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Them Feast on Fear", description = "Our grunts are strong but have no initiative. They're fighting toe-to-toe on the front lines. But an independent {class} like yourself - well, someone like you can slip behind the lines and cause some real havoc deep within the enemy redoubt.\n\nCut a swath of destruction through the heart of Talrendis, {name}! Slay our foes in territory they think is secure, leaving blood and fear in your wake.", sourceObjective = "Fight your way across Talrendis Point, slaying 12 Talrendis Defenders and 6 Talrendis Sentinels.", completion = "Lok'tar ogar, {name}! As they discover the bodies of their comrades they will learn that no place is safe from the fury of the horde, and their will to fight will crumble.", sourceObjectiveStatus = "unverified-source-field" }
quests[24434] = { id = 24434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commando Drop", description = "Are you sensitive to the tremors of the local ley-lines, {name}? I can feel the occasional thrum, like the plucking of a string. It's the kind of resonance I'd expect from a long-range summoning spell. The Lorekeepers in Talrendis, with their laughably primitive magics, are trying to summon in backup from Darnassus.\n\nWe can use this to our advantage, {name}. If you can compromise their summoning stone, we can teleport a crack team of commandos behind enemy lines.\n\nLocate the summoning stone in Talrendis!", sourceObjective = "Slay 5 Talrendis Lorekeepers and locate a Lorekeeper Summoning Stone somewhere within Talrendis Point.", progress = "If Andorel's instructions are to be believed, it should be easy to refocus the stone's energies.", completion = "Images of a great and distant tree flood your mind. Your stomach lurches as you reorient the stone, briefly filling your senses with visions of a fiery portal, a towering mountain, a frigid wasteland, and a terrible scar across the earth.\n\nAfter a moment, the magical energies of the stone calm, and you feel you are but a step away from Valormok. Andorel's invasion can begin...", sourceObjectiveStatus = "unverified-source-field" }
quests[24435] = { id = 24435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mop Up", description = "There are a lot of naga left on this beach. Looks like you have some wet work ahead of you, <son/girl>.", sourceObjective = "Kill 12 Spitelash Naga on the Shattered Strand.", progress = "After this, I think I may need to move away from the ocean. The smell of fish is almost too much to stand.", completion = "Good clean fun.", sourceObjectiveStatus = "unverified-source-field" }
quests[24436] = { id = 24436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halo Drops", description = "We've got \"soldiers\" all over the beach trying to get out of their work by dying on us. Find the slackers and use this flaregun to call in a priest to take care of the situation.\n\nWe can't have men thinking they can get off that easy.", sourceObjective = "Call in Airborne Priests at the bodies of 8 Wounded Soldiers on the Shattered Strand.", completion = "Fine job there, bud. We'll have this beach cleaned up in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[24437] = { id = 24437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Come, First Served", description = "There's some gorgeous beach front property along the shore. I can market this stuff for 10 times what construction will cost me.\n\nThe prime spots are that naga pagoda to the south, the tower right next to the water, and the ruins at the far northern end of the beach. I'll give you some coin if you claim them for me before the fighting clears out.", sourceObjective = "Plant Ruckus' Territorial Claim Flag next to the prime real estate locations along the Shattered Strand.", completion = "Hah hah! Brilliant. Right fine job there, boy.", sourceObjectiveStatus = "unverified-source-field" }
quests[24438] = { id = 24438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exodus", description = "We have no choice, {name}.  We must move further inland.\n\nI don't like it one bit, but we're vulnerable here.\n\nReturn to the stables below the manor.  Let's get everybody on carriages and send them eastbound.  I pray it's not too late.", sourceObjective = "Board a carriage below Greymane Manor.", completion = "Thanks for stopping, {name}.  Our carriage got hit pretty bad.\n\nThe one in front of us got it worse.", sourceObjectiveStatus = "unverified-source-field" }
quests[24439] = { id = 24439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest of Azshara", description = "{name}! Was it you who piloted the wind rider who bombed the command center? It was a direct hit!\n\nMy scouts tell me that you gravely wounded Jarrodenus, flight master of the night-elven skychasers and de facto commander of the opposition.\n\nThe opportunity to strike is now - I don't have time to assemble a full assault. Rush the command center building and kill Commander Jarrodenus before his backup arrives. Bring me his head... and Azshara is ours!", sourceObjective = "Slay Commander Jarrodenus in Talrendis Point and collect his head.", progress = "Is Jarrodenus still barking orders, or have you removed from him the burden of his head?", completion = "...Then it is done!\n\n<Chawg surveys the battlefield.>\n\nThere are still pockets of resistance around our camp, but this rearguard action appears to be masking a full-fledged retreat to Ashenvale. Azshara is ours!\n\nThe Warchief will hear of this victory and your part in it. But we will surely need the help of a {class} like you elsewhere. Be sure to speak with Kroum here in camp before you leave.", sourceObjectiveStatus = "unverified-source-field" }
quests[24440] = { id = 24440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterhoof Cleansing", description = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  The well is to the southeast, but be warned: whoever did this may still be there, laying in wait.\n\nThis may prove very dangerous, {name}.  Be careful...but do not let the defilers of our well escape.", sourceObjective = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well.", progress = "Do not delay, {name}.  The Winterhoof Well must be purified!", completion = "The Grimtotem...\n\n<Mull scowls.>\n\nI'd hoped to see the end of my days before {race} attacked other {race} senselessly on the very plains of Mulgore.  But be proud, {name}.  You have done a great thing for the land, and for our people.", sourceObjectiveStatus = "unverified-source-field" }
quests[24441] = { id = 24441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderhorn Totem", description = "There is more work to be done.  We must create a new totem to cleanse the Thunderhorn Well.\n\nYou must gather the claws of the predators of the Mulgore plains.  Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws, then return to me.\n\nYou will find the prairie stalkers and flatland cougars to the east and west.", sourceObjective = "Collect 6 Stalker Claws and 6 Cougar Claws.", progress = "{name}, do you have the claws I sent you to gather?  The Thunderhorn Water Well grows more tainted with each passing hour!", completion = "Thank you, {name}.  The purity with which these beasts hunt is vital in the creation of the next cleansing totem.\n\nThe Thunderhorn Well is a symbol of my own tribe, and to know it is being desecrated by our own kind raises a fury in me I haven't felt for years.", sourceObjectiveStatus = "unverified-source-field" }
quests[24442] = { id = 24442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Plans Of The Kvaldir", description = "Looking over the captured attack plans, you find a map of the Eastern Kingdoms and Kalimdor with major settlements marked. Reading over the orders, you learn that  Kvaldir captains have drafted plans for a series of devastating raids.\n\nAccording to the orders, the attacks are to begin after Mistcaller Yngvar \"consults the Heart of the Mists.\" Perhaps you could delay the attacks by capturing the omen from the Mistcaller's Cave on the western side of Hrothgar's Landing and notify Justicar Mariel Trueheart.", sourceObjective = "Recover the Heart of the Mists and bring it and the Kvaldir Attack Plans to Justicar Mariel Trueheart at the Argent Tournament Grounds.", progress = "What is it that you've found, {name}?", completion = "<Mariel accepts the orders and the captured seeing crystal and examines both.>\n\nGood work, {name}, and quick thinking. I'm sure the theft of this trinket won't slow them down for long, but I think you've bought us time to warn the leaders of the Horde and Alliance about the impending attacks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24443] = { id = 24443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Hunter", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Honu Staghunter, a young hunter trainer of ours, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save her!", sourceObjective = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Honu Staghunter.", sourceObjectiveStatus = "unverified-source-field" }
quests[24444] = { id = 24444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Shaman", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Miira Thunderhoof, a young shaman trainer of ours, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save her!", sourceObjective = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Miira Thunderhoof.", sourceObjectiveStatus = "unverified-source-field" }
quests[24445] = { id = 24445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Druid", description = "It's fallen to some of our youngest to defend our camp, {name}, and many of our bravest apprentices are out there as we speak, fighting the quilboar.  I fear for their safety...\n\nPlease, look for the young druid Keshu Treehoof to the east, deep within quilboar territory. If you find her and the other apprentices alive, they may be able to help you.", sourceObjective = "Find Keshu Treehoof.", sourceObjectiveStatus = "unverified-source-field" }
quests[24446] = { id = 24446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Sunwalker", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Bowe Dawnhorn, a young Sunwalker, away in one of their foul cages. Please, find a key on one of the quilboar's bodies and go save him!", sourceObjective = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Bowe Dawnhorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[24448] = { id = 24448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Promotion", description = "Commander Molotov sent word directly that you should be dispatched to our forward post. We're preparing to send squads into the ruins to rout the naga and recover the artifact, and he would like you to lead one of them.\n\nGet to the northwest corner of the beach and follow the path up to our forward post.", sourceObjective = "Report to Captain Tork at the forward post in the Ruins of Eldarath.", completion = "{name}! You made it in one piece, good.\n\nWe've got a lot of work for you to handle for us inside the ruins, but we're sending you in with the best to take care of it. You're working with GAMA Force now, Goblin Army: Mergers and Acquisitions. Molotov says you can handle it - that's all I need to hear.", sourceObjectiveStatus = "unverified-source-field" }
quests[24449] = { id = 24449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shore Leave", description = "We're looking pretty good here at this point. It's definitely been a pleasure working with you, soldier.\n\nIf you're ready to take the artifact back, we've got a Gyrocopter ready to take you back to Bilgewater Harbor so that you can deliver it to Uncle Bedlam personally.", sourceObjective = "Bring the Heart of Arkkoroc to Uncle Bedlam in Bilgewater Harbor.", progress = "Ah, the man of the hour!", completion = "And you come with the artifact! The operation was a success then. Mergers and Acquisitions can definitely handle themselves. This thing will fetch quite a pretty penny.\n\nAnd you - I heard you did some impressive work down there. You may well have cut-down expenses by 10% single-handedly. That's the kind of smarty businessman I want in my army!\n\nHere are your wages, as promised. And a little something extra too - I hope you like it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24451] = { id = 24451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience With The Arcanist", description = "I've placed an enchantment on the tabard that should allow you to slip past the Silver Enclave's defenses for a short period of time. You should have enough time to find your way up to the top level of the Silver Enclave and meet up with the Silver Covenant's man there, known as Arcanist Tybalin.\n\nWhile disguised, obtain the copy of Ancient Dragonforged Blades that his men borrowed from Wyrmrest, and return the book to me.", sourceObjective = "Retrieve the Ancient Dragonforged Blades tome from Arcanist Tybalin.", progress = "Did you recover the book from Wyrmrest?", completion = "Excellent work. Now that this is in our hands, we must get it to Myralion Sunblaze as soon as possible. We can't risk the Silver Covenant taking the book from us again.\n\nI'll get that tabard back to Shandy and see that he's well compensated for his assistance. Once the book is in Myralion's hands, the Silver Covenant won't be a threat anymore.", sourceObjectiveStatus = "unverified-source-field" }
quests[24452] = { id = 24452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profitability Scouting", description = "Things seem to be quieting down a bit. Gallywix will probably keep forking out cash to keep us posted here, but I have a feeling we might be able to milk a bit more out of the deal.\n\nNaga and Sea Giants aren't normally friends, so the naga must be controlling them somehow. Take this stealth field generator, get in those ruins, and let me know if you find something that looks really pricey.", sourceObjective = "Use the stealth field generator to infiltrate the Ruins of Eldarath and identify the Heart of Arkkoroc.", progress = "Our stealth field generator has the same acronym as our rocket launcher. Probably poor planning on our part.", completion = "Hahah! Sweet deal. I'll get the ball rolling on this. All I need now is to find a buyer and get the go-ahead from Uncle Bedlam.\n\nHere are your wages for your work here. Excellent work, soldier.", sourceObjectiveStatus = "unverified-source-field" }
quests[24453] = { id = 24453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Private Chat", description = "Look... one last favor before you run off.\n\nPrivate Worcester is still back at that tower \"recruiting.\" Go and let him know that we're good to pack it up now. Back to town.\n\nPleasure working with you, recruit.", sourceObjective = "Speak to Private Worcester at the Orgrimmar Rocketway Exchange.", completion = "What?! I got left out of the action completely? Are you serious?\n\nAlright, alright... no shooting the messenger. Thanks for the news, bud. Maybe I'll see you back at town.", sourceObjectiveStatus = "unverified-source-field" }
quests[24454] = { id = 24454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return To Caladis Brightspear", description = "We must get this book to Caladis Brightspear immediately. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at keeping the Sunreavers at bay.\n\nTake it with you to Quel'Delar's rest, south of the Argent Tournament Grounds in Icecrown. Caladis and the sword will be waiting. The sooner we can identify the blade, the sooner we can claim it.", sourceObjective = "Bring Ancient Dragonforged Blades to Caladis Brightspear at Quel'Delar's Rest.", progress = "We've been expecting your return. What has kept you?", completion = "<Caladis accepts the heavy book and begins leafing through it.>\n\nI knew the symbols on the blade were familiar. The weapon was most certainly forged by the dragons and gifted to one of the mortal races, but which blade is this, and how did it come to rest in Icecrown?", sourceObjectiveStatus = "unverified-source-field" }
quests[24455] = { id = 24455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rapid Deployment", description = "You will be reporting for active duty immediately. Captain Desoto is overseeing deployment just down the ramp at the rocket launch station.\n\nMake us rich, soldier. Dismissed!", sourceObjective = "Report to Captain Desoto in Bilgewater Harbor for deployment.", completion = "Nice to meet you soldier. Commander Molotov speaks highly of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24456] = { id = 24456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderhorn Cleansing", description = "The Grimtotem are a tribe that believe all of Kalimdor should belong to the tauren alone. Their hate and anger led to a corrupting thirst for power. Magatha, their leader, poisoned our High Chieftain, Cairne Bloodhoof, and attempted to take Thunder Bluff for herself; she was defeated, and the Grimtotem exiled.\n\nNow they seek to ruin Mulgore itself as they are driven out. Quickly, {name}, you must go to the Thunderhorn Water Well in the north and perform the ritual!", sourceObjective = "Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well.", completion = "You've done great honor for both me and my ancestors today.  Please, take this with my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[24457] = { id = 24457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Vision", description = "I cannot thank you enough for cleansing my tribe's well, {name}, and for fighting the savage Grimtotem to do it. But there is more to be done, and it is time for your journey to lead you beyond Bloodhoof Village.\n\nZarlman Two-Moons stands by the fire in the north end of the village.  Go speak with him and learn of the next ritual you must undertake.", sourceObjective = "Speak with Zarlman Two-Moons in Bloodhoof Village.", completion = "I sensed you would be coming to me, {class}. I can always recognize one who is trying to pass the Rites of the Earthmother.", sourceObjectiveStatus = "unverified-source-field" }
quests[24458] = { id = 24458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hello to Arms", description = "{name}, I've taken the purified sample of Azsharite you rescued from the lab and I've weaponized it. If my calculations are correct, it will detonate with enough force to level a city.\n\nIf I'm wrong, we may cleave the planet in two.\n\nThe only way to find out is a test-firing! Deliver the Azsharite core to the giant cannon in Bilgewater and report to Bleenik Fizzlefuse. My pilot-for-hire Friz Groundspin here can give you a ride.\n\nI'll follow... from a safe distance.", sourceObjective = "Deliver the Armed Azsharite Core to Bleenik Fizzlefuse at Bilgewater Harbor. Speak with Friz Groundspin for a free airlift.", progress = "What's that you've got there - did Grapplehammer send you?", completion = "Oh! This is it! It's the big one!\n\n<Fizzlefuse calls out to his workers.>\n\nWe're in business boys!", sourceObjectiveStatus = "unverified-source-field" }
quests[24459] = { id = 24459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morin Cloudstalker", description = "You may have heard of the Venture Company. They are a goblin \"cartel\", something like a tribe.\n\nWhile one of these cartels has joined us in the Horde, the Venture Company is loyal only to greed. These greedy goblins and their workers have tried to exploit the resources of Mulgore before, to little success.\n\nOne of our outrunners, Morin Cloudstalker, has gone to check the remains of one of the goblin caravans. If you wish to help him, follow the road out of the village to the east.", sourceObjective = "Find Morin Cloudstalker to the east of Bloodhoof Village.", completion = "Well met. If Ahmo has already explained the minor quibbles of what kind of goblin we'll be driving from our lands, let's get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[24460] = { id = 24460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Order", description = "Hey there {class}, I need you to solve the Cataclysm. Go hunt me some zombies.  You are |5{race}.", sourceObjective = "Paul's Test Questgiver wants you to kill zombies.", sourceObjectiveStatus = "unverified-source-field" }
quests[24461] = { id = 24461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforging The Sword", description = "We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel.\n\nIn the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar.\n\nYou must gather bars of infused saronite and capture the forgemaster's hammer, then bring them to the forgemaster's anvil and reforge the sword.", sourceObjective = "Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer and use them to make the Reforged Quel'Delar.", progress = "Were you able to reconstruct Quel'Delar?", completion = "You have remade the blade of Quel'Delar, although Blood-Queen Lana'thel proclaimed we could not! The blade must still be tempered, but she and her master will not stand in our way!", sourceObjectiveStatus = "unverified-source-field" }
quests[24463] = { id = 24463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probing into Ashenvale", description = "Even as the Darnassian scum pull back from Azshara, I've been getting mixed reports from my riders stationed in Ashenvale, to the west. The night elves may be making an assault on our territory in the Barrens.\n\n{class}, I need you to slip across the border and speak to one of my scouts. Look for Kulg Gorespatter just across the bridge at the southwest edge of Talrendis Point. Find out what's happening in those woods!", sourceObjective = "Speak with Kulg Gorespatter in Ashenvale.", completion = "You say Talrendis Point has fallen? That's good news!\n\nIt also explains the exodus of elves I've seen along this road.", sourceObjectiveStatus = "unverified-source-field" }
quests[24467] = { id = 24467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fade to Black", description = "Now we put an end to all this madness. We need to rout the black dragonflight from Azshara entirely before they can return with any communication for their master.\n\nI still don't know what they have up their sleeve for capturing us, so I'd like to ask this one last thing of you - go into sable ridge and kill their leaders, Twilight Lord Katrana and Malicion.\n\nIf things get hairy, I will come help. I just don't want to risk falling into whatever trap they set for Azuregos.", sourceObjective = "Kill Twilight Lord Katrana and Malicion in Sable Ridge.", progress = "I will be glad to be done with these wretches.", completion = "You truly amaze me, mortal. It's rare to meet someone so dedicated and resourceful.\n\nAzuregos and I are likely to depart Azshara and remain discrete for a while. I do hope that we meet again someday though. Perhaps to put an end to Deathwing himself.\n\nFarewell, {name}. Stay safe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24468] = { id = 24468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranded at the Marsh", description = "The ogres got two of our stagecoaches: this one and one that fell into the marsh just north of here.\n\nI want you to head there and rescue any survivors while we hatch up a plan to deal with these ogres.", sourceObjective = "Rescue 5 Crash Survivors at the Hailwood Marsh.", progress = "Were any of the passengers still alive?", completion = "You've done it again, {name}.  You have my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24469] = { id = 24469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hold the Line!", description = "Hey, you there!  Ye're a stout-looking {class}.  Lend us a hand?\n\nIt looks like today's big earthquake shook a bunch o' those barbarous troggs out of the ground, and they're sure steamed about something.  My men are doing what they can to hold them off, but we could use a hand.\n\nDo yer part - head just south of here and help dig me mountaineers outta trouble.  We've got to hold the line!", sourceObjective = "Slay 6 Rockjaw Invaders.", progress = "How many of 'em did ya get?", completion = "Impressive work, laddie.  We can hold the perimeter from here on out.\n\nHere, take this for yer troubles.  It might come in handy, as I've got something more important to ask of ye...", sourceObjectiveStatus = "unverified-source-field" }
quests[24470] = { id = 24470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give 'em What-For", description = "Alright, {name}, listen up.  I know a thing or two about troggs, and one of those things is that the biggest, strongest troggs get the most respect.  The brutes value strength over anything else.\n\nYe see those great big troggs sitting back behind the front lines?  They're the closest they have to what ye'd call a leader.  Go take out a few, and show 'em what it means to mess with the Sons of Ironforge!", sourceObjective = "Kill 3 Rockjaw Goons.", progress = "Well, what're ye waitin' for, {class}?", completion = "Hmm... they blame us for destroying their home, ye say?  Well, that wasn't us, that was the horrible earthquake we had earlier today.  Are they that dense that they can't see we nearly lost our camp too?\n\nCan't blame a trogg for fightin' for his home, though.", sourceObjectiveStatus = "unverified-source-field" }
quests[24471] = { id = 24471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid for the Wounded", description = "{name}, listen!  Unlike Joren, I've no need for yer blade, but I do need someone with a steady hand and a bit o' courage.\n\nOur mountaineers are trained to protect the village from the odd wolf attack... not an all-out trogg invasion!  Many of our best have succumbed to wounds and exhaustion, and I need yer help bandaging them up.\n\nHere, take my first aid kit and assist as many as ye can.", sourceObjective = "Use Sten's First Aid Kit on 4 Wounded Coldridge Mountaineers.", progress = "Thanks for yer help, {name}.", completion = "Many of those that y'saved have already made it back to camp.  The wounds're well-dressed!  Ye might have a future in first aid, if ye're into that sorta thing.", sourceObjectiveStatus = "unverified-source-field" }
quests[24472] = { id = 24472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Introductions Are in Order", description = "The Forsaken are right on our heels and now these ogres are trying to flank us, {name}.\n\nThey're servants of the ettin Koroth -- the meanest, most destructive force in all of Gilneas.\n\nIf we can bait Koroth into charging the Forsaken's forward force, we should be able to cover our retreat and buy some time.\n\nThe only way this can work is if we make Koroth furious.  It won't be enough to just kill his minions.  We need to swipe his most prized possession, a tiger-skinned banner.", sourceObjective = "Kill 4 Ogre Minions and obtain Koroth's Banner in Koroth's Den.", progress = "How did it go, {name}?", completion = "You definitely got the ettin angry, {name}.   I heard him myself.\n\nLet's hope this works.", sourceObjectiveStatus = "unverified-source-field" }
quests[24473] = { id = 24473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lockdown in Anvilmar", description = "We appreciate yer help out here, but there may be a place where they need ye even more.\n\nDue to the trogg attacks - not to mention that massive earthquake we just had - we're putting all civilians on lockdown inside Anvilmar, just up the hill to the northwest.\n\nGo an' talk to me wife, Jona, inside Anvilmar.  I'm certain she's in need of an able-bodied <man/lass> such as yerself.", sourceObjective = "Speak with Jona Ironstock in Anvilmar.", completion = "Achh.. and what do YOU want?  Can't ye see I'm busy in here!  Go an' bother someone else, I haven't the time.\n\nWait, what's that ye say?  Joren sent you to help?  Well why didn't ye say so?", sourceObjectiveStatus = "unverified-source-field" }
quests[24474] = { id = 24474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Things First: We're Gonna Need Some Beer", description = "I don't know how ANYONE expects to get any work done around here if we don't have any ale!  Our beer level here in Anvilmar is dangerously low.\n\nLucky for us, we've stowed some backup kegs for just such an occasion.  West of Anvilmar, along the valley's northern border, ye'll find kegs of Stormhammer Stout and Theramore Pale Ale.  Just to the east of here, ye'll find a stash of Gnomenbrau.  That's me personal favorite.", sourceObjective = "Obtain a Cask of Stormhammer Stout, a Cask of Theramore Pale Ale, and a Cask of Gnomenbrau.", progress = "The ale, darling, the ale!", completion = "<Jona drinks deeply from the Gnomenbrau.>\n\nAhh... that hits the spot.  Now we can get some work done around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24475] = { id = 24475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All the Other Stuff", description = "If we're going to be on lockdown for any extended period o' time, we're gonna need some food, and some blankets to keep the wee ones warm.  Would ye mind headin' outside and gatherin' up some supplies?\n\nYe'll find that a few o' the small boars actually have some healthy-sized haunches... good for eatin'.  We'll also need some pelts from the young wolves.\n\nYe'll find animals almost anywhere ye go in Coldridge.", sourceObjective = "Obtain 3 Boar Haunches and 4 Ragged Wolf Hides.", progress = "The people are gettin' restless.  D'ye have the supplies yet?", completion = "This'll have to do for now.  We've a lot of people to feed here, but we've got to make do with what we've got.  With any luck, King Bronzebeard in Ironforge will send us some help shortly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24476] = { id = 24476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempering The Blade", description = "At last, the pieces of Quel'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything.\n\nDeep in Icecrown Citadel's Forge of Souls is a place where the blade can safely be tempered. Take Quel'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me in The Frozen Halls.", sourceObjective = "Temper the Reforged Quel'Delar in the Crucible of Souls.", progress = "Until the sword is tempered, it will be useless.", completion = "I... I don't understand. Tempering the sword should've restored the blade to its original condition. What has happened here?", sourceObjectiveStatus = "unverified-source-field" }
quests[24477] = { id = 24477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dwarven Artifacts", description = "{name}, my <boy/beautiful flower>!  Are you into archaeology?\n\nWe've an exciting opportunity right outside our front door.  All the shaking from today's seismic event has knocked a number of artifacts loose from the soil around our encampment.  Survey along the valley's northern border, and you should find all sorts of treasures.  Bring some back to me, and perhaps we can study them together.\n\nRight, then!  Off you go!", sourceObjective = "Obtain 5 Forgotten Dwarven Artifacts.", progress = "Yes?", completion = "Wonderful!  Look at this one... it must be over 200 years old!\n\nNow, onto other matters...", sourceObjectiveStatus = "unverified-source-field" }
quests[24478] = { id = 24478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Frost", description = "You know, some of my apprentices have called me cold hearted. I always say though, I shall not let the temperature of my body parts stand in the way of true learning.\n\nTo reach the Trial of Frost, touch the Frost crystal to open a portal. Once there, the goal is quite simple - gather the little floaty ice orb thingies.\n\nTo counter the simple, the rotating Frostburns may put back your progress, as it were. If you want to be fancy, you can use the rune traps to jump over them as they rotate by. Neat, eh?", sourceObjective = "Complete the Trial of Frost by gathering 20 Essence of Ice without getting hit by Frostburn.", progress = "No. Just no. Do it right this time.", completion = "Brilliant. You certainly don't let cold feet stop you. Or cold any part for that matter!\n\nNo? ...too soon?", sourceObjectiveStatus = "unverified-source-field" }
quests[24479] = { id = 24479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Shadow", description = "Let us not be confined by the bounds of the mage repertoire of magic. I, for one, choose not to be classist. Necromancy can just be so much fun!\n\nTouch the Shadow Crystal to open a portal to my Trial of Shadow. Once there, move to the Altar when you are ready to begin.\n\nWeeping Souls shall begin to pursue you... your goal is simply to drag them into the traps. And be sure not to let them touch you.", sourceObjective = "Complete the Trial of Shadow by luring 20 Weeping Souls into the shadow runes without getting touched.", progress = "You're not very good at this. You're supposed to complete the trial BEFORE you come talk to me again. Make sense?", completion = "I like the way you move, apprentice.\n\nDon't you worry about where I got all the souls from. They were obtained in a perfectly humane manner, I assure you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24480] = { id = 24480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Halls Of Reflection", description = "You have reforged and tempered the sword, yet it sits quietly in its sheath, showing no signs of the power it should possess. You say the sword pulls you, as though it possesses a will?\n\nDare you bring it where it wishes to go? It's not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Take it into Icecrown Citadel's Halls of Reflection, but be on your guard! I'll be waiting for you in The Frozen Halls.", sourceObjective = "Bring your Tempered Quel'Delar to Sword's Rest inside the Halls of Reflection.", progress = "What happened inside the Halls of Reflection?", completion = "I had not thought it possible for evil to take hold in such a sword, but I suppose it was naive of me. If the greatest of dragonkind's creations could be corrupted and turned against them, why not a mere sword?\n\nUther's advice is wise, {name}, and I would urge you to heed it quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24483] = { id = 24483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormglen", description = "Our carriage drivers were told to regroup in the fishing town of Stormglen.  Our scouts report there might be shelter and supplies to be found there.\n\nMeet Gwen Armstead there, she'll be in charge of taking care of our people.", sourceObjective = "Speak to Gwen Armstead in Stormglen.", completion = "It's good to see you made it, {name}.  It looks like most everybody did.\n\nWe're not doing too bad so far for an emergency evacuation.", sourceObjectiveStatus = "unverified-source-field" }
quests[24484] = { id = 24484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest Control", description = "Well, what do you know, {name}?  All this time and Stormglen's been left mostly intact.\n\nIt's too bad the Forsaken are still working their way inland, but it'll make a fine place to rest our feet for a night or two.\n\nThe other half of town is overrun with spiders, so I've asked the villagers to stay away from there.\n\nPerhaps you'd like to lend a hand in clearing the spiders out?  I'm certain our injured men and women will sleep more soundly if they know someone's keeping those eight-legged beasts at bay.", sourceObjective = "Kill 6 Vilebrood Skitterers in Stormglen.", progress = "You're back, {name}.  Have the spiders been taken care of?", completion = "You've done well, {name}.  The spiders are everywhere, however, and I'm afraid we've barely put a dent in their numbers.", sourceObjectiveStatus = "unverified-source-field" }
quests[24486] = { id = 24486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Hay While the Sun Shines", description = "The trogg village to the southwest suffered similar damage to ours.  One would assume, logically, that there would be some trogg artifacts sticking out of the ground, too!\n\nUnfortunately, it looks like most of the artifacts have already been scooped up by trogg scavengers.  Please, go see if you can find some way to get them back.  Believe it or not, knowledge about troggs may eventually lead to further knowledge about the mighty dwarves!", sourceObjective = "Obtain 5 Priceless Rockjaw Artifacts from Rockjaw Scavengers.", progress = "Did you manage to pry any artifacts from the troggs?", completion = "Well would you look at this!  An axe blade, a couple of arrowheads, and what appears to be some sort of rudimentary spoon.  This is indeed fascinating.\n\nThanks again for your help, {name}.  I've much studying to keep myself occupied while Joren's got us under lockdown.", sourceObjectiveStatus = "unverified-source-field" }
quests[24487] = { id = 24487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitebeard Needs Ye", description = "Ye've done us a great service here, but I'm afraid I've gotta send ye off elsewhere.\n\nGrelin Whitebeard, a good friend of mine, has put in word that he may need some reinforcements near the troll camps to the southwest.  Follow the road westward, ye should find him soon enough.\n\nBe well, {name}.  Troggs may be a pain, but trolls are a whole other type of trouble.", sourceObjective = "Report to Grelin Whitebeard's camp in Coldridge Valley.", completion = "Welcome, {class}.  Are you ready to get to work?", sourceObjectiveStatus = "unverified-source-field" }
quests[24488] = { id = 24488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Replacements", description = "My guys are all on the injured roster! Our shredders are all kaput! The ref is about to call the game!\n\nIt's down to the wire and I need you, {name}!!!\n\nLet's get one of these shredders in working condition. There are replacement parts all over Bilgewater Port. Any green-blooded Kezanian will gladly let you have them if there's a chance that the Buccaneers will win.\n\nWe'll show those no-good Steamwheedle Sharks how to play footbomb!", sourceObjective = "Collect 6 Replacement Parts.", progress = "We're counting on you, {name}!", completion = "That's my boy! Now to get one of these useless hunks of metal in working order and you into the game!", sourceObjectiveStatus = "unverified-source-field" }
quests[24489] = { id = 24489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolling for Information", description = "I'm notoriously bad at reading troll facial expressions.  That being said, these trolls don't look angry to me.  They seem to be confused... maybe a little frightened.\n\nSomething happened that we're not seeing here, {name}.  I say we do some investigation before we just kill every troll in sight.\n\nThere are three troll camps in the area: one to the southeast, one to the southwest, and one due west.  Each camp has a soothsayer... see if you can get close enough to listen to what they're saying.", sourceObjective = "Stand near a Frostmane Soothsayer in each of the Frostmane camps and listen to what they have to say.", progress = "I can't even begin to imagine what would make the trolls act like this.", completion = "Hmm... interesting.  From what you're saying, it sounds like a fire elemental might have snuck in from Searing Gorge.  Or, the earthquake opened up a crack to the elemental plane...\n\n<Soren laughs uncomfortably.>\n\nEither way, this is bad news.  You should probably report this information to Grelin.", sourceObjectiveStatus = "unverified-source-field" }
quests[24490] = { id = 24490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trip to Ironforge", description = "The presence of a fire elemental here in Coldridge is no small matter.  That earthquake did more than just upset a bunch of troggs... it changed the world enough to tear a gash into the elemental plane.  We should submit a report to Ironforge.\n\nYou wouldn't be willing to take a trip, would ya?  Don't worry, I've a feeling that you'll do just fine.  Talk to Hands Springsprocket by the tunnel on the eastern edge of the valley.  He'll point you in the right direction.", sourceObjective = "Report to Hands Springsprocket in Coldridge Valley.", completion = "To Ironforge?  Well first, you'll need to go through Kharanos, and before that, you'll have to go through this tunnel.", sourceObjectiveStatus = "unverified-source-field" }
quests[24491] = { id = 24491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow that Gyro-Copter!", description = "D-d-did you see that?  How the whole cave just crumbled like that?  I guess it's good that you got here when you did, and not a minute earlier.\n\nWhile this development makes my job of monitoring the cave entrance much easier, I imagine it makes it a lot harder for you to get to Kharanos.\n\nHey wait, I've got an idea!  The Gnomeregan Airmen have a flight path not far from here.  I'll send up a signal, and they should be here to help.  I imagine they'll land back over at Anvilmar.", sourceObjective = "Report to Milo Geartwinge near Anvilmar.", completion = "Milo Geartwinge, reporting for duty.  You sent up a distress signal?", sourceObjectiveStatus = "unverified-source-field" }
quests[24492] = { id = 24492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pack Your Bags", description = "The weight limit on my gyro is such that I only have enough room for one {race}.  Looks like you're in luck, {name}!\n\nThat dwarf woman Jona told me that most of your personal belongings have been moved inside Anvilmar.  Please gather what you'll need, finish up any affairs that remain, and return to me when you're prepared for takeoff.", sourceObjective = "Obtain a Coldridge Beer Flagon, a Ragged Wolf-Hide Cloak, and some Leftover Boar Meat.", progress = "Are you absolutely certain you've taken care of everything?  You won't have time to turn back.", completion = "Took you long enough.  Hold on tight, and take a good hard look!  Chances are you won't be coming back here for quite some time.", sourceObjectiveStatus = "unverified-source-field" }
quests[24493] = { id = 24493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget About Us", description = "You're leaving?  Make sure you stock up before you head out.\n\nMore importantly, please speak to Tharek Blackstone once you arrive in Kharanos.  Tell him what has happened here in Coldridge, and that we could use some assistance.  Hopefully he'll be able to arrange something for us.", sourceObjective = "Report to Tharek Blackstone in Kharanos.", completion = "Coldridge Valley?  I've got my own problems here!  What, they can't deal with a couple of troggs?  And trolls?  And incursions from the elemental plane?\n\nActually, on second thought, that's kind of a lot.  I'm surprised they're doing as well as they are.  I'll see what I can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[24494] = { id = 24494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowered Rune", description = "{name}, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the shaman trainer Teo. Take a gander at it and go find him inside Anvilmar.", sourceObjective = "Read the Empowered Rune and speak to Teo Hammerstorm in Anvilmar.", progress = "The spirits have forewarned me of your arrival, {name}.  Have you heard them too?", completion = "These are dark days, friend.  Look around you... even here in remote Coldridge, the spirits are rebelling.  The land is crying out for help.  Yet still, even in times such as these, the spirits will always turn an ear to those who ask for their assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[24495] = { id = 24495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces of the Past", description = "I found a journal by a man named Bradshaw.  Unfortunately it's missing many pages.  Especially towards the end.\n\nIf you find enough of the pages I might be able to piece together what happened here after the Curse broke out.\n\nWho knows... maybe the people in this town found a way out.   Maybe there are still survivors out there.\n\n Maybe my father is still alive.", sourceObjective = "Obtain 6 Old Journal Pages.", progress = "Any luck finding those pages?", completion = "Thank you, {name}.  It will take some time, but I'll try to make sense of what we have.", sourceObjectiveStatus = "unverified-source-field" }
quests[24496] = { id = 24496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Rune", description = "{name}, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the mage trainer Teegli. Take a gander at it and go find her inside Anvilmar.", sourceObjective = "Read the Arcane Rune and speak to Teegli Merrowith in Coldridge Valley.", progress = "I see that Jona's given you my runic message.  Do you still have it with you?", completion = "The power of the arcane is everywhere, {name}.  Only some of us have the ability to see it, and fewer still possess the ability to master it.\n\nYou are one of those few.", sourceObjectiveStatus = "unverified-source-field" }
quests[24497] = { id = 24497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Airborne Again", description = "We just got word from Valormok that we can't send anymore windriders that way unless we want them shot down by Talrendis snipers. We can't give up Valormok if we want a secure route to Ashenvale, so we're going in another way.\n\nThe airborne priests have graciously offered to drop some people in for us from above sniper range. Head up to the military area and secure a ride on one of their planes. They'll get you there in one piece, and hopefully once you're there, you can resecure our windrider lines.", sourceObjective = "Secure a ride to Valormok with the Airborne Priests in the eastern portion of Bilgewater Harbor.", completion = "It's past time that these night elf scum be purged from Azshara. Glad to have an able body like you to sink the point home.\n\nReady to get to work?", sourceObjectiveStatus = "unverified-source-field" }
quests[24498] = { id = 24498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to the Citadel", description = "They've put our captured soldiers to work in the quarry!\n\nKill their captors and set them free, hero. We will need their aid when we confront Scourgelord Tyrannus.", sourceObjective = "Free 15 Alliance Slaves and kill Forgemaster Garfrost.", progress = "My men and I appreciate your help, {class}. More than we could possibly express in these trying times.", completion = "You've done well this day. With many of the slaves freed and now with access to the forges, it will not be long before I have a strong force to aid in delivering us from Scourgelord Tyrannus and this foul pit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24499] = { id = 24499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Tortured Souls", description = "We're severely undermanned to be risking a venture into the citadel, but opportunities like this are too rare to pass up.\n\nClear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the citadel.", sourceObjective = "Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.", completion = "Just in time! Thank you, {name}.\n\nThe Pit of Saron lies ahead, and if our scouts are correct, past that will be the Halls of Reflection. It is there that Arthas lets his guard down, and it is there that we hope to find a clue to his weakness... or maybe, just maybe, his redemption.", sourceObjectiveStatus = "unverified-source-field" }
quests[24500] = { id = 24500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King", description = "It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?\n\nMany questions remain. but you need to find Jaina and escape the Lich King while there's still time.", sourceObjective = "Find Lady Jaina Proudmoore and escape the Halls of Reflection.", completion = "<Jaina is still catching her breath.>\n\nI can barely believe we're still alive. It was foolish of me to follow him. I've made that mistake too many times.  And you... it was reckless of you to come after me instead of escaping with the information! But... well... thank you. You truly are a hero.\n\nWith Uther's guidance, we may stand a chance at defeating Arthas. All the lives lost today were not in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[24501] = { id = 24501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Queen-Sized Troubles", description = "The spiders keep coming in alarming numbers, {name}.  You're going to have to go into their lair and kill the broodmother.\n\nWe've spotted the giant spider known as Rygna at the edge of the Blackwald in an area covered in thick webs.  It'll be dangerous, but we're all counting on you.", sourceObjective = "Slay Rygna at Rygna's Lair.", progress = "Did you take care of Rygna, {name}?", completion = "Great job, {name}.  We've heard rumors of survivors further in the mountains.  Now we'll be able to send scouts there.", sourceObjectiveStatus = "unverified-source-field" }
quests[24502] = { id = 24502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necessary Roughness", description = "We're down to our last shredder. While no one was looking, I loaded it up with, shall we say, modified footbombs.\n\nKid, I need you to get in that shredder and give 'em heck!", sourceObjective = "Get into the Bilgewater Buccaneer and then throw the Footbomb at 8 Steamwheedle Sharks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24503] = { id = 24503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fourth and Goal", description = "It's all up to you, kid. You demolished the Steamwheedle Sharks, so now all that's left to do is to kick the winning goal.\n\nNow, just between you and me, I think we should do this one right. I don't want you to just kick a goal... I want you to kick it so far it sails between the two smokestacks behind the goal!\n\nI've modified the footbomb to give you the extra power that you'll need.\n\nMake me proud!", sourceObjective = "Score the winning goal by kicking the Footbomb through the smokestacks behind the opposing goal.", completion = "Uh... you did it, kid. You REALLY did it! We won the game and....\n\nDID YOU SEE THAT DRAGON?!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[24504] = { id = 24504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the High Road", description = "This way, {class}! I see you've discovered the high road.\n\nThe Alliance hopes to sever our ties with Stonetalon, but they forget that we tauren have hunted across these lands for generations. We know every hillside switchback and game trail from here to Thousand Needles.\n\nBut for these paths to stay open, we must stop the humans from mapping them out.\n\nPatrol the trail east and kill any high road scouts you find along the way, then speak to Tunawa Stillwind just up the path.", sourceObjective = "Slay 3 High Road Scouts.", completion = "Patrolling the high road is grave business, but it must be done. These narrow mountain trails are, for the time being, one of our only lifelines into Stonetalon. They must be preserved.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24505] = { id = 24505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holdout at Hunter's Hill", description = "Honor's Stand may have been lost, but its spirit was never crushed. Even now survivors are holding out at a point called \"Hunter's Hill.\"\n\nContinue following the high road and you will find our camp just up ahead. Speak with Onatay when you get there and let her know the trail is, for the moment, still clear.", sourceObjective = "Speak with Onatay at Hunter's Hill in Southern Barrens.", completion = "So the Alliance is probing the twists and turns of the high road?\n\nEven if they were to map it out, they couldn't attack these hills in numbers. This is our land, {name}. And they will pay dearly for presuming otherwise.", sourceObjectiveStatus = "unverified-source-field" }
quests[24506] = { id = 24506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inside the Frozen Citadel", description = "{class}! Come close quickly, I must have a word!\n\nMy queen, the Lady Sylvanas Windrunner, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \"The Forge of Souls.\" She sent word before she left for me to find fierce fighters to send her way. I think you'll do.\n\nGo to her within the entrance to the forge, {class}.", sourceObjective = "Enter The Forge of Souls from the side of Icecrown Citadel and locate Lady Sylvanas Windrunner.", completion = "Good. {name}, I know of you. You'll be perfect for these tasks.\n\nWe've been afforded a rare chance to delve into Icecrown Citadel, but we must move quickly if we're to avoid Arthas' notice.", sourceObjectiveStatus = "unverified-source-field" }
quests[24507] = { id = 24507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to the Citadel", description = "They've put our captured soldiers to work in the quarry.\n\nKill their captors and set them free, {class}. We will need their aid when we confront Scourgelord Tyrannus.", sourceObjective = "Free 15 Horde Slaves and kill Forgemaster Garfrost.", progress = "Thank you, {class}. You will have our blood and our steel behind you this day.", completion = "You've done well this day. With many of the slaves freed and now with access to the forges, it will not be long before I have a strong force to aid in delivering us from Scourgelord Tyrannus and this foul pit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24508] = { id = 24508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temp Quest Record" }
quests[24509] = { id = 24509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temp Quest Record" }
quests[24510] = { id = 24510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inside the Frozen Citadel", description = "{class}! Come close quickly, I must have a word!\n\nMy patron, the Lady Jaina Proudmoore, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \"The Forge of Souls.\" She sent word before she left for me to find any help that I could... and, well, I was hoping that might be you.\n\nPlease, find her there as soon as you can.", sourceObjective = "Enter The Forge of Souls from the side of Icecrown Citadel and find Lady Jaina Proudmoore.", completion = "{name}! I'm so glad you've come.\n\nWe've been afforded a rare chance to delve into Icecrown Citadel, but we must move quickly if we're to avoid Arthas' notice.", sourceObjectiveStatus = "unverified-source-field" }
quests[24511] = { id = 24511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Tortured Souls", description = "Delving into the citadel with so few is risky at best, but opportunities like this are too rare to pass up.\n\nClear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the Citadel.", sourceObjective = "Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.", completion = "Well timed, {class}!\n\nThe Pit of Saron lies ahead, and if our scouts are correct, past that will be the Halls of Reflection. It is there that Arthas lets his guard down, and it is there that we hope to find a clue to his weakness... and a route to vengeance long overdue.", sourceObjectiveStatus = "unverified-source-field" }
quests[24512] = { id = 24512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warriors' Redemption", description = "Those that surrendered when Honor's Stand fell are no longer worthy of our Horde, {class}. But I'm not giving up on them yet. The prison tower below us is lightly guarded. Let's give those prisoners one final chance to die with honor.\n\nI've set up ropes that will allow you to quickly clamber up and down the mountain. Slip down, acquire the confiscated weapons, and re-arm the prisoners inside the tower.\n\nAnd {name}, stay by the tower! We're not yet equipped for an assault on the base proper.", sourceObjective = "Acquire 5 crates of Confiscated Arms from Honor's Stand and re-equip 5 Stonetalon Prisoners. Use the nearby ropes to quickly sneak in and out of the Alliance camp.", completion = "From up here I got the perfect view of the havoc you just caused, {name}. Our lost brothers reclaimed some of their dignity, and the Alliance dogs were sent scrambling. Sharp work, my friend!\n\nIf the Alliance sleeps comfortably at night, we are not doing our job.\n\nWe will never let up.\n\nWe will never give in.", sourceObjectiveStatus = "unverified-source-field" }
quests[24513] = { id = 24513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye for an Eye", description = "Who goes there? Your footsteps are not the lazy stride of a guard.\n\nA {class}, you say? Still brave and free? There's no hope for me, friend. I have lost my eyesight and am no longer fit for battle.\n\nI dared speak up while Captain Peake savagely beat one of the prisoners. In return he kicked me in the head. And kept kicking. He kicked me blind, {race}.\n\nYou'll find Captain Peake at the top of this tower. If you seek justice, bring me his eyes.\n\nIf he does not part with them willingly... so be it.", sourceObjective = "Slay Captain Peake and deliver his eyes to Oltarg.", progress = "Peake is a monster. If his superiors knew, they would thank the Horde for ending him.", completion = "You have them? I'll take your word for it. Hearing Peake scream like one of his victims is reward enough for me.\n\nNow leave me be, {name}. I do not wish to be a burden to my clan.", sourceObjectiveStatus = "unverified-source-field" }
quests[24514] = { id = 24514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Scraps", description = "We are besieged here, {class}, and between that chasm and the harassment of the Alliance we are short on supplies. But we make do with what's at hand, as we tauren always have.\n\nIn the absence of a forge, a skilled leatherworker can strengthen and patch up our damaged armor with good quality hides.\n\nDown below is the hunting ground of the Terrortooth Raptors. They are not so easy to kill, in part due to the ruggedness of their thick skin. Hunt them, {name}, and bring their hides to me!", sourceObjective = "Gather 8 Terrortooth Hides from Terrortooth Runners and Terrortooth Scytheclaws.", progress = "Terrortooth raptors hunt in packs and surround their prey. We hunt them, yes; but we also respect them.", completion = "<Onatay looks over the fresh hides, nodding her head slowly.>\n\nYes {name}, I can work with these. You work fast!\n\nThese hides will help us hold out for reinforcements longer. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24515] = { id = 24515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signals in the Sky", description = "Turn your eyes to the southeast. Do you see the campfire smoke from Camp Una'fe?\n\nNot ten minutes ago I saw great puffs of white smoke roll up into the sky from the center of camp. It was an old signal used by my village to coordinate the hunt over great distances, but this time, it was a distress signal.\n\n{name}, my brother Makaba had gone into that unnatural jungle. Please go there and make sure he's not in any trouble.\n\nThere are few paths: look for tents within the wilderness.", sourceObjective = "Travel to Camp Una'fe in the Overgrowth of Southern Barrens and speak with Makaba Flathoof.", completion = "So my sister recognized the old signals? Her hunter's eyes are as sharp as ever.\n\n{name}, when we first set up this camp we were at the edge of this jungle. Now look at it!\n\nSomething is amiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[24517] = { id = 24517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put the Fear in Them", description = "Do you see the trail below us, {name}? That is MY trail. And if the Alliance dogs choose to use my trail, they'd best be looking over their shoulder.\n\nIt's time to collect my toll! Slay the footsoldiers from Honor's Stand and see if we can't send them scurrying back to their walls.\n\nBe sure to take out at least one of their officers patrolling the road. They need to realize that nobody is safe.", sourceObjective = "Kill 8 Honor's Stand Footmen and 1 Honor's Stand Officer.", completion = "Excellent, {name}. It will be some time before we can assault the hold proper, but until then, we must teach them to fear the Barrens.", sourceObjectiveStatus = "unverified-source-field" }
quests[24518] = { id = 24518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Low Road", description = "This bundle of papers was found in a leather satchel hidden under the officer's clothes.\n\nBattle maps of the region depict Honor's Stand, connected to what appears to be a large unfinished roadway crossing the Barrens all the way from Theramore. It looks like the Alliance plans to build a road from the coast straight into the heart of Kalimdor!\n\nKilrok Gorehammer will want to see this.", sourceObjective = "Deliver the Roadway Plans to Kilrok Gorehammer at Hunter's Hill in Southern Barrens.", progress = "Ah, you say you found something on one of the bodies?", completion = "<Kilrok pages through the plans you discovered.>\n\nThis explains much, {name}. No wonder our foes are so hellbent on taking the southern Barrens. It's at the center of their plans for the continent!\n\nBut they didn't account for us, did they {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24519] = { id = 24519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalling the Survey", description = "These maps have all been drawn by the same steady hand. I've seen a human surveyor heading up and down the road between the hold and the jungle to the east.\n\nWe can set their plans back by making an example out of this surveyor, {name}.\n\n<Kilrok points to the signature at the bottom of the maps.>\n\nWhat do you think that says? \"Zykes?\" Even human names sound thin and weak. Kill him.", sourceObjective = "Find and kill the surveyor Henry Zykes.", completion = "Good, good. We've got to keep Honor's Stand isolated.\n\nAlone ... afraid ... {name}, if we keep up the pressure, maybe someday they'll simply surrender the pass.", sourceObjectiveStatus = "unverified-source-field" }
quests[24520] = { id = 24520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Sassy the News", description = "I'd celebrate with you, {name}, but it feels like that dragon did a number on ol' Mount Kajaro. I... uh... I think I'm gonna grab my stuff and get on the first ship leaving the island!\n\nAnyways, you should probably head back to headquarters and let Sassy know that you won the footbomb title for us. I'm sure she'll also want to know about the dragon and Mount Kajaro.\n\nGood luck!", sourceObjective = "Speak with Sassy Hardwrench at KTC Headquarters on Kezan.", completion = "You're kidding, right?! DEATHWING?!!!\n\n<Sassy looks panicked for a moment.>\n\nOkay, this'll work out just fine. We'll throw your party and by the time it's over, I'm sure that the dragon will be long gone and the ground will stop shaking.\n\nIf not, we can always charter a ship off of the island.", sourceObjectiveStatus = "unverified-source-field" }
quests[24522] = { id = 24522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey To The Sunwell", description = "Take Quel'Delar to the Sunwell as quickly as possible, {name}. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword.\n\nThe guardians of the Sunwell will not simply allow you to walk in, so you must find Halduron Brightwing, who will be inspecting the guards there.", sourceObjective = "Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas.", progress = "What brings you here?", completion = "Admit you to the Sunwell? That's impossible! The Sunwell is the most sacred and important site of our people. We have only recently reclaimed it with the help of the Shattered Sun Offensive. It is not a place for tourists or travelers.", sourceObjectiveStatus = "unverified-source-field" }
quests[24523] = { id = 24523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildmane Totem", description = "There is but one water well left to cleanse, named after the Wildmane clan.  For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha.  Find the alphas to the north, then return to me when your hunt is finished.\n\nAlphas often wander around the base of our mighty city, Thunder Bluff.", sourceObjective = "Collect 4 Prairie Alpha Teeth from Prairie Wolf Alphas.", progress = "{name}.  Do you have the teeth I asked for?", completion = "Very good, {name}.  I can feel the sacrifice of the land in this offering, and my spirit swells with sadness, and pride.", sourceObjectiveStatus = "unverified-source-field" }
quests[24524] = { id = 24524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildmane Cleansing", description = "Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young {name}.  The Wildmane Totem is made, and your last task lies ahead.\n\nThe Wildmane Water Well lies north of Thunder Bluff.  Perform the ritual!  Heal the land of the Grimtotem's poisons!  Let clean water flow once again!", sourceObjective = "Use the Wildmane Cleansing Totem at the Wildmane Water Well.", completion = "You've done it.  You have cleaned the wells, and healed our land.  Bloodhoof village is grateful, {name}.\n\nMay the wind whisper your deeds for a hundred seasons, and may the waters of Mulgore remain clean forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[24525] = { id = 24525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Dogs at Bay", description = "Not everyone who fled Taurajo was able to make it to Una'fe, {name}. Some died of wounds along the way. Others were jumped by opportunistic quilboar.\n\nI'll take care of the grim task of finding and gathering the bodies. But there is something you can do for me.\n\nHecklefang scavengers prowl the lands south of here and are savaging the corpses, tearing at their bowels and dragging away the limbs of the dead. Please, thin their numbers so that I can perform the proper funerary rites.", sourceObjective = "Kill 6 Hecklefang Scavengers.", completion = "So it is done.\n\nNormally these scavengers are part of the Earthmother's cycle of life. But on the heels of the devastation wracked by both the Alliance and the cataclysm, their numbers grow overwhelming. It is good to thin them out.", sourceObjectiveStatus = "unverified-source-field" }
quests[24526] = { id = 24526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling Up the Spellbook", description = "Excellent!  Let's get started.\n\nAs you grow in power, your connection to the arcane arts will deepen, and you'll gain access to new spells and abilities.\n\nGo, get some more experience, and you'll see what I mean. Come back when you learn something new and demonstrate it on the training dummies here.", sourceObjective = "Reach level 3 to learn Frost Nova. Successfully cast it 2 times on the Training Dummies outside the entrance to Anvilmar.", progress = "You can do this, {name}.  Get out there and blast those dummies!", completion = "There we go!  One spell down, many many more to go.  Come back to me after you've had some experience casting this spell, and I'll show you some more tricks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24527] = { id = 24527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Path Begins Here", description = "Excellent!  Let us begin.\n\nAs you grow along your journey, you will unlocked the ancient secrets of shamans. \n\nPrimal Strike is the first such skill.  The primal spirits, when called upon, will strengthen your arm to deliver a mighty blow.\n\nHelpful, isn't it?", sourceObjective = "Reach Level 3 to learn Primal Strike, and then use Primal Strike 2 times on a Training Dummy near the entrance of Anvilmar.", completion = "This has been but one of many footfalls on the long path of the {class}.  Come back to me after you've had some experience in the field, and I will help guide you on your next step.", sourceObjectiveStatus = "unverified-source-field" }
quests[24528] = { id = 24528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of the Light", description = "Are ye ready to start?  Wonderful!  We're glad to have ye.\n\nAs ye get stronger, it brings ye closer to the light, and ye learn new techniques. Go ahead and get some more experience, and show me what ye learn.", sourceObjective = "Reach level 3 to learn Seal of Command. Use Seal of Command on yourself, and then hit one of the Training Dummies at the entrance to Anvilmar.", progress = "Seal of Righteousness is great! I feel righteous right now!", completion = "There, ya did it.  The Light favors quick learners like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24529] = { id = 24529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad to Worse", description = "When the refugees fled north from Taurajo, some were separated as darkness closed in. Many were taken prisoner by the Bristleback quilboar who set up camp west and southwest of here.\n\nI am not certain what the quilboar hoped to get from us by capturing our refugees; all they have earned is my ire. And all they'll get in return is vengeance.\n\nRescue my trapped brothers and sisters, and kill their captors to send a message to the quilboar.", sourceObjective = "Rescue 5 caged Taurajo Refugees, and kill any combination of 8 Bristleback Thornweavers or Bladewardens.", completion = "It's bad enough to have one's village sacked... but to spend the following night in a quilboar cage? I'm glad you were there to help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24530] = { id = 24530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, A Hunter's Life For Me", description = "The life of a hunter is steeped in tradition, ye know.  Trackin' mighty beasts through rugged terrain.  Drinkin'.  Travelin' the land, yer gun at yer side.  Drinkin'.  Survivin' on wits and courage and cunning, followed by a good stiff drink.\n\nBut before we get to the good stuff, though, ye'll need to learn how to do the beginner stuff.\n\nGo and get some more experience, and ye'll figure out how to do more things. Then ye' drink.", sourceObjective = "Reach level 3 to learn Steady Shot, then use Steady Shot 5 times on the Training Dummies outside the entrance to Anvilmar.", progress = "I know the {class}'s life is exctin' now, but you jus' wait... it gets even better.", completion = "Now that ye've got a new {class} trick under yer belt, go out there an' track some beasts!", sourceObjectiveStatus = "unverified-source-field" }
quests[24531] = { id = 24531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Battle-Ready", description = "Lesson one.  Aside from your sword and shield, what's the most important tool you have in your arsenal?\n\n<Thran awaits your response.>\n\nOh never mind, I'll answer it for you.  It's experience.\n\nAs you get more experience, you'll discover new techniques, which means you can be much more effective than you imagined.\n\nGo, get some experience, and learn something new. Then come back and demonstrate.", sourceObjective = "Reach level 3 to learn Charge, then use Charge on one of the Training Dummies outside the entrance to Anvilmar.", completion = "Now we're getting somewhere.  You've got quite a manly bellow, sir!\n\nCome back to me in a bit, and I'll teach you something else.", sourceObjectiveStatus = "unverified-source-field" }
quests[24532] = { id = 24532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evisceratin' the Enemy", description = "When you get to be more experienced, you'll start to find you can take advantage of new abilities. \n\nOne of the things that you'll learn is the ability to use combat maneuvers to weaken an opponent, and then hit them with a devastating technique.\n\nGo and get some experience, figure out how to do it, and then try it out on some of the dummies here.", sourceObjective = "Reach level 3 to learn Eviscerate, then use Eviscerate 3 times on the Training Dummies near the entrance to Anvilmar.", progress = "No, this isn't just my way of getting your money.  I'm doing this for your own good.\n\nReally.", completion = "You've got the hang of it.  Go get some practice out there... maybe take out a few of those troggs or trolls.  Or rabbits, I don't care.\n\nReturn after you've gotten some practice, and I'll show you another trick of the trade.", sourceObjectiveStatus = "unverified-source-field" }
quests[24533] = { id = 24533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of Power", description = "Now, if ya DO want to become somethin' special, ye'll need to talk to me.  A priest is nothin' without his spells.  And how do you learn new spells?\n\nYa go and get more experience. So go out, get stronger, and then come show me what ya learn.", sourceObjective = "Reach level 3 to learn Shadow Word: Pain, then cast it 5 times on training dummies.", completion = "Well done, {name}.  You'll make a fine {class} in due time.\n\nReturn to me after you've proven yourself a bit more, and I'll reward you by teaching you another spell or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[24534] = { id = 24534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking Their Language", description = "The quilboar are attacking because they perceive weakness. Strength is the only language they understand. So we will show them strength.\n\n<Makaba withdraws a large horn from his satchel.>\n\nThis is admittedly crude work but it'll do. Bristleback leaders use horns like these to challenge one another for dominance.\n\n{name}, I want you to challenge the Bristleback champion, Sabersnout, to single combat. Defeat him in front of his followers. Blow the horn at the Bristleback challenge ring due south of here.", sourceObjective = "Blow the Horn of Challenge in the Bristleback Challenge Ring, and defeat Sabersnout in single combat.", progress = "Have you taken the Bristlebacks down a peg or two?", completion = "What? He attacked you with a dozen boars? I guess quilboar have their own ideas of what \"single combat\" means.\n\nStill, the Bristleback will be left reeling after the blow you delivered. It will not be long before a new champion rises amongst them to stir up trouble... but at least this buys us some time to get these refugees relocated safely.\n\nThank you, {name}. The survivors owe you a great debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24535] = { id = 24535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Dawnseeker", description = "If you truly bear Quel'Delar, {name}, I might be able to admit you to the Sunwell. If you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", sourceObjective = "Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar.", progress = "Did you visit the ground where Thalorien fell defending the Sunwell?", completion = "I confess that I did not expect Thalorien's spirit to recognize you as the heir to Quel'Delar, but I defer to his judgment. You may enter the Sunwell, but I remind you that you are a guest in the most our most sacred of precincts, and you should act accordingly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24536] = { id = 24536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Stinks", description = "Get a load of these guys, would ya? Steamwheedle's been handling the business of holidays for years, and all of a sudden, these guys bust into the market. They're not Steamwheedle; the cartel hired me to get to the bottom of this. Something stinks here and it ain't just perfume.\n\nTake this device I brought and go analyze the perfume clouds around the guards. I want to know what they're putting in that stuff. Things ain't natural.", sourceObjective = "Use Snagglebolt's Air Analyzer to test the air around 6 heavily perfumed guards, then return to Detective Snap Snagglebolt in Orgrimmar.", progress = "You analyze that reek yet, kid?", completion = "Hey, thanks, kid. Give it over, let's take a look.\n\n<He takes the device from you and fiddles with it.>\n\nOh, that ain't good.", sourceObjectiveStatus = "unverified-source-field" }
quests[24539] = { id = 24539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Plants Attack", description = "This camp was built at the edge of this jungle, and already it is overwhelmed by plant growth. Something unnatural is happening here!\n\nEarlier I made the mistake of sending some of the healthier refugees out to gather nuts and berries. Those that returned talked about the plant life actually grasping at their legs or even picking them up. I worry about those that haven't come back yet.\n\n{class}, please rescue the refugees trapped in the grasping overgrowth around the camp.", sourceObjective = "Rescue 5 Taurajo Refugees by killing the Grasping Overgrowths that ensnare them.", completion = "Thank you, {name}. But now on to the larger question:\n\nWhere is this overgrowth coming from? And why is it raging out of control?", sourceObjectiveStatus = "unverified-source-field" }
quests[24540] = { id = 24540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Dance", description = "Some see our people as gentle giants, or noble savages. They have never seen us fight against our own kind...against betrayers from within.\n\nThe Grimtotem were offered mercy in exile, and they have scarred their own home to spite us. They will no longer be tolerated in Mulgore.\n\nI've already sent our warriors ahead to drive them out through Stonetalon Pass, to the north. You have fought bravely against the Grimtotem, {name}; I ask that you join the battle again. Go, and help deal this final blow.", sourceObjective = "Defeat Orno Grimtotem at Stonetalon Pass.", completion = "Welcome back, {name}.\n\n\n\nWhat was done was not for revenge, or pride. It was simply to protect Thunder Bluff, and all our people, from torment and fear. Today, Mulgore is safe once more.\n\nThe Earth Mother thanks you for all your brave deeds, {name}, as do I. You have earned your reward, hero. May you be welcome in Thunder Bluff always.", sourceObjectiveStatus = "unverified-source-field" }
quests[24541] = { id = 24541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfering Perfume", description = "I knew they were up to no good! There's some sort of mind-affecting chemical in here, but I can't get a handle on it with such a small sample. I need the real stuff.\n\nDon't just go over there and buy it! I don't want you giving these scumbags one copper. Nah, you gotta get it from the source, discreet-like.\n\nI'll disguise you as a package runner. I saw a stockpile guarded by their goons outside the gates. Go run by, and DON'T stop, or they'll make you! They'll toss you a crate. Bring it back here.", sourceObjective = "While disguised as a package-runner, go to the Crown Chemical Company's stockpile outside the gates of Orgrimmar, then return the package they toss you to Detective Snap Snagglebolt in Orgimmar.", progress = "Did they toss ya a crate to deliver?", completion = "You got it, huh? Good job, kid. Top notch. Let's see what we got here.\n\n<He cracks open the crate and rummages around inside.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24542] = { id = 24542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Bloom", description = "The great archdruid Naralex recently appeared here in the Barrens. He's either behind this mess or trying to fix it. Either way, you should talk with him before this jungle engulfs the whole world! He's in a small tauren camp to the southeast.\n\nAlong the way, it would be helpful for you to gather plant samples for him to study. The newest flower buds will tell him a great deal about the most recent changes in the jungle.", sourceObjective = "Gather ten Unusual Flower Buds from Budding Flowers in the Overgrowth.", progress = "I am extremely busy, {class}.", completion = "Ah, samples from different parts of the overgrowth? These will be immensely helpful, yes. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24543] = { id = 24543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Family Divided", description = "The children you see here were all rescued from Taurajo when the fighting started. I'm trying to track down their parents.\n\nOne of the refugees you rescued from the quilboar recognized the strongest child as belonging to Kirge and Mawre Sternhorn. Moreover, he said Kirge was camped at the Fields of Blood, just north of the Taurajo massacre site.\n\n{name}, please go there and tell Kirge Sternhorn that his child is alive and well!", sourceObjective = "Find Kirge Sternhorn at Vendetta Point in Southern Barrens.", completion = "<Kirge listens intently and then falls to one knee.>\n\nAlive! My boy still lives! Praise to the earthmother, I still have a son.\n\n<Kirge composes himself.>\n\n{class}, my boy's mother didn't make it out of Taurajo alive. I will avenge her death, even if it means my son grows up without either of his parents.", sourceObjectiveStatus = "unverified-source-field" }
quests[24545] = { id = 24545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sacred and the Corrupt", description = "It is against my judgment that I present you this errand, {race}, as it will likely end in your undoing.\n\nIgnore my counsel and embark on the endeavor, and I shall provide you with the knowledge and resources to see it through.\n\nYou must return to Frostmourne Cavern and recover Light's Vengeance, Arthas' discarded hammer. Reforged with saronite and etched with the acidic blood of the Lich King's abominations, it will provide the foundation for our work.", sourceObjective = "Place Light's Vengeance, 25 Primordial Saronite, Rotface's Acidic Blood, and Festergut's Acidic Blood in Highlord Mograine's runeforge in Icecrown Citadel.\n\nRotface's Acidic Blood and Festergut's Acidic Blood may only be obtained in the 25 person difficulty setting of Icecrown Citadel.", progress = "As you draw near, the forge's flame seems to burn even more ravenously...", completion = "A deep sense of dread washes over you as the flame devours the items.", sourceObjectiveStatus = "unverified-source-field" }
quests[24546] = { id = 24546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Line in the Dirt", description = "The Alliance scorches a trail of murder across the Barrens. We must stop them here or there is nothing left for us.\n\nAcross the Fields of Blood there are a number of strategic hills, marked by wooden towers and neutral gray banners. We must take and hold these hills if we hope to slow the Alliance advance!\n\nLook for the towers to the north, east, and south of what's left of Taurajo. Claim a neutral flag and defend the hill against counterattack!", sourceObjective = "Capture a neutral hill in the Fields of Blood and defend it against an Alliance counterattack.", progress = "Is the Alliance putting up a fight? How goes the battle for the Barrens?", completion = "So you held your ground! With tenacity like yours we may yet drive the Alliance from our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[24547] = { id = 24547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Feast of Souls", description = "Shadow's Edge is among the greatest weapons a {class} could hope to obtain.\n\nIs your lust for power sated, {race}?\n\n<You feel Mograine's penetrating gaze.>\n\nI thought not. A final warning then...\n\nYou now embark on the most treacherous leg of your quest. Bridle your aspirations, for if your aims are impure then your life, your very soul, is forfeit.\n\nThe weapon you hold is but an empty husk, a mere shadow of what it may become.", sourceObjective = "Highlord Darion Mograine wants you to use Shadow's Edge to slay 50 of the Lich King's minions in Icecrown Citadel. Souls can be obtained in 10 or 25 person difficulty.", completion = "<Highlord Mograine eyes you in silence for a moment.>\n\nYou seem to have endured this leg of your trial admirably, {race}.\n\nPray that fate continues to smile upon you in your endeavor...", sourceObjectiveStatus = "unverified-source-field" }
quests[24548] = { id = 24548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Splintered Throne", description = "The Lich King's throne once served as his prison. Kil'jaeden himself crafted the vessel of icy crystals from the twisting nether, its sole purpose to hold Ner'zhul's vengeful spirit.\n\nWhen Arthas struck the crystal with Frostmourne, he released Ner'zhul's soul, allowing it to merge with his own. Splinters from that impact are now scattered throughout the citadel.\n\nI shall require those shards, held only by the Lich King's most powerful servants, to seal the power contained in your blade.", sourceObjective = "Highlord Darion Mograine wants you to collect 50 Shadowfrost Shards.\n\nShadowfrost Shards may only be obtained in the 25 person difficulty setting.", progress = "Have you obtained the shards of the frozen throne, {class}?", completion = "These should suffice, {class}.\n\nSpeak to me when Shadow's Edge has been thoroughly empowered and I will attempt its completion.", sourceObjectiveStatus = "unverified-source-field" }
quests[24549] = { id = 24549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmourne...", sourceObjective = "Highlord Darion Mograine wants you to bring him Shadow's Edge.", completion = "Congratulations, {class}.\n\nAgainst insurmountable odds, you have weathered the storm.\n\nI trust that you shall find your reward proportionate to your conviction...", sourceObjectiveStatus = "unverified-source-field" }
quests[24550] = { id = 24550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey into Thunder Bluff", description = "The wells are cleansed, and Mulgore's waters run sweet and clear once more. You've saved us...but you've also uncovered grim happenings. The actions of the Grimtotem must be made known.\n\nIt is time for you to enter Thunder Bluff, our great city atop the mesa.  Go to our leader, Baine Bloodhoof, son of Cairne. He must hear of this.", sourceObjective = "Speak with Baine Bloodhoof in Thunder Bluff.", completion = "Welcome to Thunder Bluff, {name}. You've done great things for our people.\n\nTell me of your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[24551] = { id = 24551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the New Boss", description = "Our defense of the Barrens hasn't gone well under Gar'dul's command, {name}. Garrosh has sent Warlord Bloodhilt here to take control of the situation. He's here in camp, and if you want to make a good impression, you'll demonstrate some initiative.\n\nHead east into the Fields of Blood and seek out Northwatch recon units. Bringing the new Warlord a stack of their merit badges will help you make a name for yourself!", sourceObjective = "Kill Northwatch Recon patrols and collect 10 Theramore Merit Badges.", progress = "You look like the type of {class} who gets things done. What news do you have from the field?", completion = "<Bloodhilt looks at the badges, then allows them to spill from his hands onto the sands below. His lips curl open into a toothy grin.>\n\nNow THIS is what I like to see, {class}! What is your name again?\n\nYou will go far here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24552] = { id = 24552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lion's Pride", description = "If you seek vengeance on our Alliance invaders, you would do well to observe the fiercest of predators in the Barrens.\n\nThe lions that stalk amongst the tall grass do so with cunning, stealth, and power. Learn from their example and you will understand the kind of war we need to fight.\n\nHunt the plains prowlers and pridemanes, then return to me to discuss what you have learned. You will often find them in the shade of large trees.", sourceObjective = "Kill any combination of 5 Plains Prowlers or Plains Pridemanes.", completion = "Ah yes... I see a cunning in your eyes that was not present before. Well done, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24553] = { id = 24553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to me and to the rest of my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. The blade will bond to you. When that happens, carry it to Caladis Brightspear at Quel'Delar's Rest.", sourceObjective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened during your time in the Sunwell?", completion = "This is unbelievable, {name}. You've really done it! All of the quel'dorei have heard of Thalorien Dawnseeker and Quel'Delar, but no one ever thought the sword would be restored.", sourceObjectiveStatus = "unverified-source-field" }
quests[24554] = { id = 24554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battered Hilt", description = "This battered old sword hilt has seen better days. Before the hilt was snapped from the blade, it must've been a magnificent example of the blacksmith's art.\n\nThe graceful symbols and exotic gemstones decorating the hilt suggest that the weapon may have belonged to a powerful person. Surely, the Sunreavers would be interested in hearing about the recovery of such an artifact. Seek out their representatives at Quel'Delar's Rest, to the south of the Argent Tournament Grounds.", sourceObjective = "Bring the Battered Hilt to Myralion Sunblaze at Quel'Delar's Rest, south of the Argent Tournament Grounds.", progress = "What have you discovered?", completion = "<Myralion takes the hilt from you and scrutinizes the artifact.>\n\nThis came from the citadel? What was it doing there? This blade is certainly not of Scourge manufacture.\n\nWeapons of this quality can only be crafted by a few of Azeroth's creatures. We will have to consult them and see if they can help us identify it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24555] = { id = 24555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What The Dragons Know", description = "There's no mistaking it - this hilt comes from a powerful, ancient weapon, but which one? I do not recognize these particular markings, but we haven't hit a dead end yet.\n\nKorialstrasz, better known as Krasus, has long been a friend to the quel'dorei and the Kirin Tor. With his vast knowledge and resources, he's certain to know something. Travel to the top of Wyrmrest Temple and seek his counsel, then report to Magister Hathorel inside Sunreaver's Sanctuary in Dalaran.", sourceObjective = "Speak to Krasus at the top of Wyrmrest Temple.", completion = "We must recover that book from the Silver Covenant. Without that book from Krasus, we stand little chance of solving the mystery of the sword in Icecrown or unlocking its power.", sourceObjectiveStatus = "unverified-source-field" }
quests[24556] = { id = 24556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suitable Disguise", description = "Getting you inside the Silver Enclave will be tougher than it appears. Only those who possess Silver Covenant tabards are permitted entry to sanctuary. If we can get our hands on one, a simple enchantment will do the rest of the work.\n\nOn the balcony above Threads of Fate, you'll find Shandy Glossgleam. I've helped him a few times in the past, so he owes me a favor. He handles laundry for a wide variety of people in the city. Maybe he can find a way to 'lend' you a tabard for a while.", sourceObjective = "Obtain a Borrowed Tabard from Shandy Glossgleam.", progress = "Was Shandy able to help you get a Silver Covenant tabard?", completion = "I knew Shandy would find a way to make it work. Let me get this enchanted and ready for you to use. With any luck, the tabard's owner won't even know it's missing and Shandy will cover the rest of our tracks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24557] = { id = 24557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silver Covenant's Scheme", description = "One of my contacts in the Underbelly caught sight of a Silver Covenant agent gathering information at the Cantrips and Crows Tavern. Silver Covenant members aren't normally found in the sewers, so they must be plotting something.\n\nGo into the Underbelly, find this Silver Covenant agent, and eliminate him. Search the body for any information that might give us a lead on the location of that tome from Wyrmrest. We can't let those simpering Silver Covenant weaklings get it back to Icecrown before we do.", sourceObjective = "Capture the Silver Covenant Orders.", progress = "Did you find anything of use on that agent?", completion = "<Magister Hathorel reads the captured orders.>\n\nThe agent you intercepted was supposed to deliver the Wyrmrest tome to Icecrown, after meeting with one Arcanist Tybalin inside the Silver Enclave. We have to reclaim that book, {name}, and we only have one chance before it leaves the city. We have to work quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24558] = { id = 24558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return To Myralion Sunblaze", description = "We must get this book to Myralion Sunblade. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at evading the Silver Covenant's men.\n\nTake it with you to Quel'Delar's Rest, south of the Argent Tournament Grounds in Icecrown. Myralion will be waiting for you. If he can identify that blade, we may be able to claim it in the name of Aethas Sunreaver and show Dalaran and the Alliance that we will lead the charge against the Lich King.", sourceObjective = "Bring Ancient Dragonforged Blades to Myralion Sunblaze at Quel'Delar's Rest.", progress = "We've been expecting your return. What has kept you?", completion = "<Myralion accepts the heavy book and begins leafing through it.>\n\nThose symbols on the blade seemed familiar and now there's little wonder why. This is certainly a dragon blade, gifted to one of the mortal races, but which blade is this, and how did it come to rest in Icecrown?", sourceObjectiveStatus = "unverified-source-field" }
quests[24559] = { id = 24559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforging The Sword", description = "We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel.\n\nIn the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar.\n\nYou must gather bars of infused saronite and capture the forgemaster's hammer, then bring them to the forgemaster's anvil and reforge the sword.", sourceObjective = "Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer, then combine them with the Remnants of Quel'Delar to create the Reforged Quel'Delar.", progress = "Were you able to reconstruct Quel'Delar?", completion = "You have remade the blade of Quel'Delar in defiance of that Blood-Queen Lana'thel's pronouncement! Now, the blade must be tempered before we can show her the folly of her words.", sourceObjectiveStatus = "unverified-source-field" }
quests[24560] = { id = 24560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempering The Blade", description = "At last, the pieces of Quel'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything.\n\nDeep in Icecrown Citadel's Forge of Souls is a place where the blade can safely be tempered. Take Quel'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me. I'll be waiting in The Frozen Halls.", sourceObjective = "Temper the Re-forged Quel'Delar in the Crucible of Souls.", progress = "Until the sword is tempered, it will be useless.", completion = "Tempering the sword should've restored the blade. Why hasn't it worked?", sourceObjectiveStatus = "unverified-source-field" }
quests[24561] = { id = 24561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Halls Of Reflection", description = "You have re-forged and tempered the sword, yet it sits quietly in its sheath, little different from a mundane blade. You say the sword pulls you, as though it possesses a will?\n\nDare you bring it where it wishes to go? It is not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Bear it with you to Icecrown Citadel's Halls of Reflection, but be on your guard. I will wait for you in The Frozen Halls.", sourceObjective = "Bring Quel'Delar to Sword's Rest inside the Halls of Reflection.", progress = "What happened inside the Halls of Reflection?", completion = "How can evil take root in such a sword? I would not have thought it possible if the evidence wasn't here before my eyes. If the greatest of dragonkind's creations could be corrupted and turned against them, why not a mere sword?\n\nI believe Uther is right. You must heed his advice quickly, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24562] = { id = 24562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey To The Sunwell", description = "Take Quel'Delar to the Sunwell as quickly as possible, {name}. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword.\n\nThe guardians will try to stop you from entering the Sunwell Plateau, but make yourself known to Halduron Brightwing, who will be inspecting the guards there.", sourceObjective = "Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas.", progress = "What brings you here?", completion = "I hope you understand that I can't just admit you to the Sunwell, {name}. This is the most sacred place known to the sin'dorei and we have only recently regained control over it.\n\nYou would raise the hopes of our people with tales of Quel'Delar? Without proof of the truth of your claims, I see no reason to take you at your word.", sourceObjectiveStatus = "unverified-source-field" }
quests[24563] = { id = 24563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Dawnseeker", description = "You are the one working with Myralion Sunblaze, arent you? I know of a way we can test the sword.\n\nIf you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", sourceObjective = "Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar.", progress = "Did you visit the ground where Thalorien fell defending the Sunwell?", completion = "You truly do carry Quel'Delar. This is a great day for all of Quel'Thalas and the sin'dorei. You have my leave to enter the Sunwell and finish the sword's restoration. Keep your head high, {name}. The children of Silvermoon have dreamt of this day for years.", sourceObjectiveStatus = "unverified-source-field" }
quests[24564] = { id = 24564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Afterward, show the blade to Myralion Sunblaze at Quel'Delar's Rest.", sourceObjective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened inside the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24565] = { id = 24565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biological Intervention", description = "The energies unleashed here have surged through the wildlife, twisting them into powerful and unstable forms. If allowed to spread beyond this grove, these deviates will wreak havoc on the existing ecosystem, devouring local prey and driving out the weaker natural creatures.\n\nYou must go and cull the population of the overgrowth. Return when this task is done.", sourceObjective = "Kill 5 Deviate Terrortooths and 5 Deviate Plainstriders.", completion = "Thank you, {name}. I'm pleased to see you return intact; the viciousness I've been seeing among these creatures is startling.", sourceObjectiveStatus = "unverified-source-field" }
quests[24566] = { id = 24566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sowing a Solution", description = "Based on what you've brought me, I think we may have a solution. I've imbued the lashvine seeds with healing energies.\n\nSimple contact with these should imbue the creatures here with enough energy to force out the corrupted influence.\n\nGo and attempt to heal the mutated raptors and plainstriders by sprinkling the seeds on them, and report the results back to me.", sourceObjective = "Use Soothing Seeds on 6 Deviate Terrortooths or Deviate Plainstriders and observe the results.", completion = "Oh dear. It seems the forces at work here are a bit difficult to control...\n\nPlease, don't bother Naralex with this. It will only upset him.", sourceObjectiveStatus = "unverified-source-field" }
quests[24567] = { id = 24567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report for Tryouts", description = "{name}, Coach Crosscheck is looking for you. He's the leader of our fearless footbomb team, the Bilgewater Buccaneers.\n\nHe says that the division title against the Steamwheedle Sharks is on the line and that you're the only one that can bring it home for us!\n\nHead west into town. You can't miss Kajaro Field.\n\nA footbomb star. This is going to be great for your image!", sourceObjective = "Speak with Coach Crosscheck at Kajaro Field on Kezan.", completion = "There you are, my boy! Quick, there's no time to waste! We need to get one of these shredders back in working order.\n\nI'm bringing you off the bench... you're going to win the game and the title for us!", sourceObjectiveStatus = "unverified-source-field" }
quests[24568] = { id = 24568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Walls!", description = "{name}, they're massing at the gates! The Alliance is trying to push their way into Mulgore, using footsoldiers to overwhelm the guards.\n\nWe have so little with which to defend the walls. We've kept pots of water boiling to repel the attackers until help arrives... Those will have to do.\n\nBut we need someone to coordinate our defenses. Say the word and I can give you an eagle-eye view of the battlefield.\n\nWe need you, {name}!", sourceObjective = "Speak with Winnoa Pineforest at the Fields of Blood in order to defend the gates of Mulgore from attack.", sourceObjectiveStatus = "unverified-source-field" }
quests[24569] = { id = 24569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegebreaker", description = "{name}, you've proven yourself on the Fields of Blood. But the Alliance still threatens our tauren friends.\n\nThe siege machinery outside the gates of Mulgore is like a spear aimed at our heart. I want you to go to the gates, south of here, and remove those siege vehicles from play.\n\nHere, use these stickybombs. They're courtesy of our new goblin allies. It looks as though they stuffed explosive powder into ... what looks like ... grease-covered socks. But they'll do.", sourceObjective = "Destroy 4 Northwatch Siege Engines at the Mulgore Gates.", progress = "Why did Gar'dul allow the Alliance to create such a buildup of heavy siege vehicles? Why wasn't a strike ordered until I got here? Gar'dul will have to answer for this...", completion = "Very good. Now, should they storm the gates, they will have to do so with infantry.\n\nDo you think they have the stomach for that?", sourceObjectiveStatus = "unverified-source-field" }
quests[24570] = { id = 24570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adder Subtraction", description = "The corruption unleashed here must be studied if we're to find a way of properly fighting it.\n\nLuckily, not all the creatures have been as altered as others. The smaller snakes drink little water, and do not eat plants, so their exposure to the energies here has been minimal. They've still absorbed enough to change coloration.\n\nGo collect these snakes from the overgrowth and return them to me, so we can see just what is happening to the creatures here.", sourceObjective = "Collect 5 Enervated Adders.", progress = "Have you collected enough? We'll need several for proper comparison.", completion = "These will do perfectly. Bright colors like these don't occur naturally in the barrens, but they haven't developed any other mutations so far.", sourceObjectiveStatus = "unverified-source-field" }
quests[24571] = { id = 24571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lashvine Seeds", description = "There's got to be a way to cure these poor creatures without having to take their lives. I have an idea, but I'll need your help, {class}.\n\nThe lashvine plants that roam here hold seeds full of the primal energy of this place. Collect these for me and bring them back, and we'll see if something can be done.", sourceObjective = "Collect 4 Writhing Seeds from Lashvines.", progress = "Do you have the seeds?", completion = "I'm concerned by how...active these are. Nevertheless, it simply means we must continue to act quickly before the corruption here becomes worse.", sourceObjectiveStatus = "unverified-source-field" }
quests[24572] = { id = 24572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Back Taurajo", description = "Outstanding work at the gates, {name}! The main body of the Alliance force is in general retreat. But I'm not satisfied.\n\nThey sacked Taurajo, which was little more than a hunters' camp. This 'Alliance' is unmasked at last for what it really is: A renegade band of butchers.\n\nEven now a group of humans linger behind to pick at the bones of smouldering Taurajo.\n\n<Bloodhilt hurls an axe into the dirt.>\n\nMake them suffer.", sourceObjective = "Kill 8 Taurajo Looters in the ruins of Taurajo.", completion = "Excellent. I'll have their bodies strung up along the gold road as a message to the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[24573] = { id = 24573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honoring the Dead", description = "With the immediate threat gone, can you help with some grim business?\n\nWe tauren do not bury our dead, we prepare the body for its return to the elements and place it at our sacred grave sites. Those killed in the Taurajo massacre have had no funeral, and I worry misguided Alliance soldiers will burn the bodies of the dead before the proper rites have been performed.\n\n{name}, please take this totem to Taurajo and perform services for Krulmoo, Dranh, Yonada, and Omusa. They ... didn't make it out of there.", sourceObjective = "Use the Funerary Totem on the corpses of Krulmoo, Dranh, Yonada, and Omusa in the ruins of Taurajo.", progress = "Have their spirits found peace with the Earthmother?", completion = "<Winnoa bows her head.>\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24574] = { id = 24574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Harvest Chaos", description = "If I have truly sown chaos, it is time for reaping.\n\nThe lumbering outgrowths of plant life shamble through the imbued stream here, {name}. They are a direct manifestation of the unstable forces mutating this area. Slay as many as you can, and we might be able to slow the spread of the overgrowth further.\n\nAnd while you're at it...be on the lookout for parts of them that appear especially corrupted. Bring any such pieces to me.", sourceObjective = "Kill 5 Outgrowths and find a Squirming Heart.", progress = "Cutting down the outgrowth will merely buy us some time. Have you found any suspicious pieces?", completion = "<Naralex slowly takes the squirming heart from you, visibly disturbed.>\n\nI've been a fool. The one truth I did not want to accept has been staring me in the face this entire time...this foul thing is proof of that.\n\nYou and I have much work to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[24575] = { id = 24575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liberation Day", description = "We recently found out that the villagers at Emberstone survived most of the ravages of the Curse.\n\nUnfortunately their village wasn't as fortunate when it came to the Forsaken invasion.\n\nThe Forsaken have taken the villagers prisoner and are forcing them to work the nearby mine as slaves.", sourceObjective = "Free 5 Enslaved Villagers inside the Emberstone Mine.", progress = "Have you freed the villagers, {name}?  I cannot imagine what duress they're enduring under the Forsaken.", completion = "You've done it again, {name}.  The freed villagers are eager to help us against the Forsaken in any way they can.", sourceObjectiveStatus = "unverified-source-field" }
quests[24576] = { id = 24576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friendly Chat...", description = "<Roka listens with disgust as you tell her why you're trying to track down Snivel.>\n\nYou mean I've been under the spell of an alchemist all this time? I can't believe I fell for that fraud! If I ever get my hands on that conniving little goblin, I'll tear him apart!\n\nIf he's finished his errands, he's on his way down to the zeppelin tower in the middle of Orgrimmar! Whatever you do, {name}, you can't let him board that zeppelin and get away with all this!\n\nHurry to the zeppelin tower before you miss him!", sourceObjective = "Go to the zeppelin tower on the central bluff in  Orgrimmar and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.", progress = "Did you find the guy, or did he crawl under a rock?", completion = "You got his ledger? Really? That's great, {name}. There's probably loads of good information in here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24577] = { id = 24577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desolation Hold Inspection", description = "Thanks to you, the immediate threat is over. But my work here in the Barrens is only beginning.\n\nHonor's Stand was captured and Taurajo was sacked while Warlord Gar'dul was in charge of the region. The Warchief has sent me here to clean up his mess.\n\nI would like you to ride into Desolation Hold to the south in advance of me and let Gar'dul know that it is time for a reckoning.\n\nTalk to me when you are ready to leave and I will assemble my vanguard to accompany you.", sourceObjective = "Talk to Warlord Bloodhilt, then ride into Desolation Hold and inform Gar'dul that Warlord Bloodhilt is on his way.", progress = "What is this about? Why are you creating such a commotion in my camp?", completion = "<Gar'dul breaks into a sweat.>\n\nLook - ah - let's not discuss this here, in front of the men...", sourceObjectiveStatus = "unverified-source-field" }
quests[24578] = { id = 24578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blackwald", description = "It took a while, but I think I've put together what happened here.  At least partially.\n\nThere were survivors of the Curse in this town.  They joined others in the mountains, in Tempest's Reach.\n\nEveryone left, except the man who kept the journal, old man Bradshaw.  He noticed that the worgen attacks had stopped all of a sudden and decided to venture into the Blackwald.\n\nThere is an abandoned mill just northeast of town, it was where Bradshaw lived.  See if you can find any clues there.", sourceObjective = "Investigate the Bradshaw mill just outside Stormglen Village.", completion = "I've been expecting you, {name}.  Do not be alarmed.\n\nMy name is Belysra.  I am a priestess of the moon... a night elf.\n\nYou might not know my people, but the destinies of our two races have been linked since the Curse befell you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24579] = { id = 24579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sartharion Must Die!", description = "Sartharion, the Onyx Guardian, watches over the eggs of the Twilight Dragonflight. He rests within the Obsidian Sanctum in the Chamber of the Aspects underneath Wyrmrest Temple.\n\nThe Council of Six has decreed that Sartharion must die!", sourceObjective = "Kill Sartharion.\n\nThis quest can be completed with any difficulty or size raid.", progress = "Sartharion yet breathes, {class}.", completion = "With Sartharion slain, surely Deathwing and Sinestra's plans are now stalled.", sourceObjectiveStatus = "unverified-source-field" }
quests[24580] = { id = 24580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anub'Rekhan Must Die!", description = "Anub'Rekhan, once-mighty Spider Lord of the nerubian empire, has been taken by the Lich King and corrupted into a state of undeath.\n\nNow a crypt lord, he sits in his parlor in the Arachnid Quarter of Naxxramas, spinning strategies for Kel'Thuzad.\n\nThe Council of Six has decreed that Anub'Rekhan must die!", sourceObjective = "Kill Anub'Rekhan.\n\nThis quest can be completed with any difficulty or size raid.", progress = "I've heard nothing of the destruction of Anub'Rekhan. Perhaps you should redouble your efforts?", completion = "Word of your success precedes you, {class}. Anub'Rekhan is no more. You did him a great service, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24581] = { id = 24581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noth the Plaguebringer Must Die!", description = "Noth the Plaguebringer, traitor and coward! Second only to the Lich King himself for the number of souls that have been Scourged!\n\nMake haste to Naxxramas. You will find him within the Plague Quarter hiding behind his undead minions.\n\nDestroy him! The Council of Six has decreed that Noth must die!", sourceObjective = "Kill Noth the Plaguebringer.\n\nThis quest can be completed with any difficulty or size raid.", progress = "Noth yet walks Naxxramas, {class}.", completion = "That's one less thorn in our side. With Noth destroyed, Scourge research into refining the means of creating the undead will grind to a halt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24582] = { id = 24582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instructor Razuvious Must Die!", description = "Instructor Razuvious smugly struts about the Military Quarter of Naxxramas. It is said that only a death knight personally trained by him could possibly even withstand the prowess of his blade.\n\nYou and your group are going to prove everyone wrong.\n\nThe Council of Six has decreed that Razuvious must die!", sourceObjective = "Kill Instructor Razuvious.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Well done, {class}. The Scourge military command out of Naxxramas has been thrown into disarray by Razuvious's demise.", sourceObjectiveStatus = "unverified-source-field" }
quests[24583] = { id = 24583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patchwerk Must Die!", description = "The so-called \"avatar of war\", Patchwerk is the ultimate abomination. It is also taking a heavy toll upon on our forces in the Dragonblight.\n\nI want you to assemble your companions and enter the Construct Quarter of Naxxramas. Disassemble the construct.\n\nThe Council of Six has decreed that Patchwerk must die!", sourceObjective = "Kill Patchwerk.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Children everywhere will sleep easier knowing that Patchwerk is no more.", sourceObjectiveStatus = "unverified-source-field" }
quests[24584] = { id = 24584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malygos Must Die!", description = "Our resources are strained. Malygos, the Spell-Weaver, is draining all of the magic out of the world, consolidating it in the Eye of Eternity. Without magic, we are doomed.\n\n{class}, the Nexus War must be brought to an end. The Council of Six has decreed that Malygos must die!", sourceObjective = "Kill Malygos.\n\nThis quest can be completed with any difficulty or size raid.", completion = "With Malygos defeated, the Nexus War should come to a swift conclusion. You have the gratitude of the Kirin Tor, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24585] = { id = 24585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flame Leviathan Must Die!", description = "Within the Formation Grounds sits Ulduar's first line of defense: Flame Leviathan.\n\nThe Kirin Tor have been provided with information suggesting that this Keeper-created machine is soon to be transported to an undisclosed location and let loose to wreak havoc upon the mortals of Azeroth.\n\nThis must not come to pass. The Council of Six has decreed that Flame Leviathan must die!", sourceObjective = "Kill Flame Leviathan.\n\nThis quest can be completed with any difficulty or size raid.", progress = "Why is Flame Leviathan not in pieces?", completion = "I never cease to be amazed by the horrors that can be created through the use of technology.", sourceObjectiveStatus = "unverified-source-field" }
quests[24586] = { id = 24586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorscale Must Die!", description = "Razorscale normally keeps to her aerie near the Colossal Forge in Ulduar. Of late, however, she has been spotted raining fire down upon lands outside of the titan complex.\n\nThough the broodmother's is a sad tale, she poses an imminent threat to all of Northrend. The Council of Six has decreed that Razorscale must die!", sourceObjective = "Kill Razorscale.\n\nThis quest can be completed with any difficulty or size raid.", progress = "Is something wrong? Why have you not yet dealt with Razorscale?", completion = "Now Veranus can finally rest in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[24587] = { id = 24587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignis the Furnace Master Must Die!", description = "The great fire giant, Ignis the Furnace Master toils away inside of Ulduar's Colossal Forge. Under orders from Loken, Ignis creates weapons that are terrifying in their power.\n\nThe Council of Six has decreed that Ignis must die!", sourceObjective = "Kill Ignis the Furnace Master.\n\nThis quest can be completed with any difficulty or size raid.", progress = "Ignis is not yet dead. The fire giant must fall!", completion = "I trust that you did not have to face too many of his iron construct assistants?", sourceObjectiveStatus = "unverified-source-field" }
quests[24588] = { id = 24588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "XT-002 Deconstructor Must Die!", description = "Yet another strange construct of Mimiron, the XT-002 Deconstructor actually thinks that it is the keeper's son. Do not be fooled by its feigned innocence. It is a deadly machine!\n\nYou will find the Deconstructor within Ulduar's Scrapyard. The Council of Six has decreed that XT-002 Deconstructor must die!", sourceObjective = "Kill XT-002 Deconstructor.\n\nThis quest can be completed with any difficulty or size raid.", progress = "I am given to understand that you have not yet been able to deconstruct the Deconstructor.", completion = "The greatest weakness of Ulduar is its masters' blind faith in their inventions to protect it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24589] = { id = 24589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Jaraxxus Must Die!", description = "Archmage Timear has foreseen a horrible event, which is about to transpire. A foolish gnome warlock is about to accidentally summon an Eredar lord of the Burning Legion into the middle of the Trial of the Crusader.\n\nYou must be there when it happens, {class}. If Lord Jaraxxus escapes, he will open a portal and the Burning Legion will spill forth into our world once more.\n\nThe Council of Six has decreed that Lord Jaraxxus must die!", sourceObjective = "Kill Lord Jaraxxus.\n\nThis quest can be completed with any difficulty or size raid.", completion = "All of Azeroth is fortunate that Timear foresaw the Eredar lord's arrival and that you were there in time to slay him.", sourceObjectiveStatus = "unverified-source-field" }
quests[24590] = { id = 24590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Marrowgar Must Die!", description = "Lord Marrowgar is the guardian of the Frozen Throne within the Spire Chamber. Pieced together by the Lich King from the bones of a thousand vanquished adventurers, Marrowgar wields the power of the throne itself.\n\nWithout the destruction of this bone wraith, there is no hope of taking Icecrown Citadel.\n\nThe Council of Six has decreed that Lord Marrowgar must die!", sourceObjective = "Kill Lord Marrowgar.\n\nThis quest can be completed with any difficulty or size raid.", completion = "The Frozen Throne is without its chief guardian thanks to you. Our attacks upon the Lich King's forces will be all the more successful now.", sourceObjectiveStatus = "unverified-source-field" }
quests[24591] = { id = 24591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Changing of the Gar'dul", description = "When Bloodhilt arrives, I'd like to - ah - talk in private. Can you accompany me to make sure things stay on the level? This Bloodhilt is a, ah, he's a, he's a loose cannon.\n\n<Gar'dul tries to compose himself.>\n\nMeet me atop the northern tower and we'll talk with Bloodhilt together.", sourceObjective = "Go to the top of the northern tower in Desolation Hold and help Warlord Bloodhilt \"Relieve\" Gar'dul of command.", sourceObjectiveStatus = "unverified-source-field" }
quests[24592] = { id = 24592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayal at Tempest's Reach", description = "King Greymane has been taken prisoner by Lord Godfrey in Tempest's Reach!\n\nHe managed to convince two of the eastern lords to go with his plan.  The fool seems to think he can strike a deal with the Forsaken by turning Greymane over to them.\n\nListen carefully, {name}.  We need to resolve this with as little bloodshed as possible.\n\nThis potion will allow you to sneak in undetected.  We need you to assassinate the traitorous lords before this gets out of hand!", sourceObjective = "Drink Krennan's Potion of Stealth in Tempest's Reach and assassinate Baron Ashbury and Lord Walden.", progress = "Careful, {name}.", completion = "I wish it could've been avoided, {name}.  Let us ensure this is resolved without further bloodshed.", sourceObjectiveStatus = "unverified-source-field" }
quests[24593] = { id = 24593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neither Human Nor Beast", description = "It is time, {name}.  This... alchemy that has kept the beast inside you at bay will not last for long.\n\nThe first cursed worgen were night elf druids like our new allies.  They, however, abandoned the balance that the rest of their kind embraced and allowed the beast to take over their minds.\n\nIt is only fitting that their brethren be the ones that deliver us from the Curse.  Go, {class}.  Drink from the waters of Tal'doren and make peace with yourself.", sourceObjective = "Drink from the Well of Tranquility, the Well of Balance and the Well of Fury.", progress = "It is always good to see you brother.", completion = "It is done then, {name}.  You are one of us now.", sourceObjectiveStatus = "unverified-source-field" }
quests[24594] = { id = 24594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Speak to a Warden of the Sunwell to enter the Sunwell Plateau. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Show the blade to Myralion Sunblaze at Quel'Delar's Rest once it is restored.", sourceObjective = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "You have returned from the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24595] = { id = 24595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. Once the blade is restored, return with it to Caladis Brightspear at Quel'Delar's Rest.", sourceObjective = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "Tell me of what happened in the Sunwell, {name}.", completion = "This is unbelievable, {name}. You've really done it! All of the quel'dorei have heard of Thalorien Dawnseeker and Quel'Delar, but no one ever thought the sword would be restored.", sourceObjectiveStatus = "unverified-source-field" }
quests[24596] = { id = 24596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete the its restoration, then speak with Myralion Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", sourceObjective = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened during your visit to the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24597] = { id = 24597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the King of Stormwind", description = "Did you want to make a Lovely Charm Bracelet for the king of Stormwind? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to King Varian Wrynn in Stormwind.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24598] = { id = 24598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete its restoration, then show it to Myralio Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", sourceObjective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What news do you bring from the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24601] = { id = 24601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightmare Scar", description = "This confirms it. The overgrowth here is not being caused by a mere overabundance of energy.\n\nDo you understand? This is beyond what happened at the Wailing Caverns now. A rift into the Nightmare must have torn open in the middle of the very land we're standing on! And to think it's my fault...\n\nI'm done picking at the edges of this wound. Go to the west, to the center of the overgrowth, and meet me again there. We will dive into the heart of this corruption and force it shut!", sourceObjective = "Help Naralex seal the Nightmare Scar.", progress = "We must not allow the nightmare to spread further into our world!", completion = "We've done it! The nightmare's connection to this place has been severed. The rest of the land is safe from this intrusion now, and in time, the abberations here will be subsumed by the balance of nature.\n\nI cannot thank you enough, {name}. By helping to restore order here, you've let me make amends for my foolish actions.", sourceObjectiveStatus = "unverified-source-field" }
quests[24602] = { id = 24602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laid to Rest", description = "In our hurried escape for safety, we disturbed the resting homes of our ancestors, {name}.  A grave sin, if you'll pardon the pun.\n\nIt is tradition that a small memento be buried on top of a Gilnean's graveyard, beneath the shallow earth.  The stampede of people fleeing these tunnels has unearthed these mementos and angered the spirits.\n\nFind them and bring them to me.  We'll see to it that the dead return to their eternal slumber.", sourceObjective = "Obtain 5 Unearthed Mementos.", progress = "You're back, {name}.", completion = "Thank you, {name}.  Let us hope this works.", sourceObjectiveStatus = "unverified-source-field" }
quests[24603] = { id = 24603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Stop Bereavin'", description = "For a moment, I thought my hatred had stilled. My wife laid to rest, a final offering of the blood of her murderers to quell her tortured spirit. I thought perhaps peace would appeal to me.\n\nI was wrong.\n\nI will not rest now until every single filthy, squealing, murderous quilboar lays dead and broken! I cannot kill them fast enough with my own two hands.  Go and slay more for me, {race}.", sourceObjective = "Kill 13 Razormane Quilboar.", completion = "Good. Take your reward; this is only a prelude.", sourceObjectiveStatus = "unverified-source-field" }
quests[24604] = { id = 24604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concern for Mankrik", description = "I would ask a favor of you, {class}.\n\nA warrior named Mankrik passed through our camp not long ago, on a lonely journey. His wife was killed by the quilboar, long ago, and he still seeks revenge. I cannot forget his eyes...burning with inconsolable hatred, every waking moment.\n\nWe did not talk long, but I cannot bear to think of him out there alone. Please, bring this to Mankrik, and tell him it is from me...", sourceObjective = "Bring Mahka's Gift to Mankrik, south of Firestone Point.", progress = "<Mankrik snarls.>\n\nWhat is it!? I'm busy!", completion = "Mahka sent you?\n\n<Mankrik's fury quells for a moment.>\n\nIt is a small comfort. But nothing can console me until I am done here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24606] = { id = 24606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Barrens", description = "This bright red stone, found clutched in the grasp of a quilboar, has been carefully carved into the likeness of a great boar, with thorny vines sprouting from its back. Its surface is smooth and worn with care.\n\nDid the quilboar make this? If you find others, maybe one of the shaman at Firestone Point could tell you more about them.", sourceObjective = "Collect 6 Blood Shard Trinkets from Razormane Quilboar.", progress = "Yes?", completion = "These are blood shards. They used to be found all over the Barrens.\n\nIt's said they were formed from the blood of Agamaggan, the great demigod that the quilboar sprang from. I knew the quilboar prized them, but nobody would think they'd take the time and care to carve them like this one...\n\nThere may be more to learn here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24607] = { id = 24607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Nortet to the east.", sourceObjective = "Meet with Nortet in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually look ta be in shape though. Steady hands. Fierce eyes. I may be able ta turn ya into a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[24608] = { id = 24608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangletooth", description = "I no longer care for honor or glory, {class}. All that matters to me is that the quilboar die, by any means, at anyone's hand.\n\nMangletooth, the chief of these filthy Razormane, sits in his lair to the northwest, atop a hill. End his life.\n\nI plan to stay here, and pile these bodies until no more vermin run squealing from the Kraul to face me...", sourceObjective = "Kill Mangletooth.", completion = "Good.  Good! They will all die!  Their chieftains, and their women, and their children, and their foul pets!", sourceObjectiveStatus = "unverified-source-field" }
quests[24609] = { id = 24609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for a Lord of Ironforge", description = "Did you want to make a Lovely Charm Bracelet for Muradin Bronzebeard? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Muradin Bronzebeard in Ironforge.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24610] = { id = 24610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the High Priestess of Elune", description = "Did you want to make a Lovely Charm Bracelet for the High Priestess of Elune? I'm sure she'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Tyrande Whisperwind in Darnassus.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24611] = { id = 24611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Prophet", description = "Did you want to make a Lovely Charm Bracelet for the Prophet of the Exodar? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Prophet Velen in the Exodar.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24612] = { id = 24612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Warchief", description = "Did you want to make a Lovely Charm Bracelet for the Warchief? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to the Warchief in Orgrimmar.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24613] = { id = 24613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Banshee Queen", description = "Did you want to make a Lovely Charm Bracelet for the Banshee Queen? I'm sure she'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Lady Sylvanas Windrunner in Undercity.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24614] = { id = 24614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the High Chieftain", description = "Did you want to make a Lovely Charm Bracelet for the High Chieftain? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Baine Bloodhoof in Thunder Bluff.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24615] = { id = 24615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Regent Lord of Quel'Thalas", description = "Did you want to make a Lovely Charm Bracelet for the Regent Lord of Quel'Thalas? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Lor'themar Theron in Silvermoon City.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24616] = { id = 24616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Your Tail", description = "You must have many questions, {name}.  And they will be answered in time.\n\nI know why you're here and what you're looking for.\n\nI can't lead you there with the enemy tracking you.\n\nOne of Sylvanas's scouts has been following your tracks.  You can't lead the Forsaken to the place you seek.  Take this talisman and walk along the road just north of here.\n\nLet the ranger lure you to her trap and use the power of the talisman to break free and counterattack.", sourceObjective = "Use Belrysa's Talisman to defeat the Dark Scout.", progress = "Is it done, {name}?", completion = "Well done, {name}.  The scout never had a chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[24617] = { id = 24617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal'doren, the Wild Home", description = "There are others like you, {name}.  And they too, were lost and confused.\n\nThere is a place where you belong.\n\nTal'doren, the wild home, was once home to an order of druids who took the shape of wolves.\n\nIt is there that you will find the answers you seek.  It is also there that you will find someone who can offer guidance.  An old friend.", sourceObjective = "Speak to Darius Crowley at Tal'doren, in the heart of the Blackwald.", completion = "You're all right, {name}!  I've been waiting for this day for a long time, it truly is great to see you friend.\n\nI've heard of what you've done and I'm thankful... especially for Lorna -- she's all I've left.  I will send for her right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[24618] = { id = 24618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claim the Battle Scar", description = "We have fought the Alliance to a standstill here, even as the land beneath our feet falls apart. To the east you will find the Battlescar, a wide swath of decimated terrain. It is little more than a line in the sand, but it must be OUR line.\n\nIn the center of the scar you will find a flag marker designating who controls it. Scout out the flag.\n\nIf it's not already ours, capture it for the Horde - it will swing the battle in our favor. Investigate the scar and kill anyone you find in there!", sourceObjective = "Go to the Battlescar. Scout out the flag marker and kill 10 Triumph Vanguard soldiers.\n\nCapturing the flag will give all Horde players in the scar a combat advantage.", completion = "Excellent! You're my kind of {class}, {name}.\n\nWith your help, we will throw these invaders back into the sea.", sourceObjectiveStatus = "unverified-source-field" }
quests[24619] = { id = 24619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts-is-Parts", description = "I've always wanted to try making an abomination. It looks simple enough, but you know how it is when you learn things from a book. There's no substitute for doing!\n\nFirst, I'm going to need parts. Lots of parts. And you're going to get them for me.\n\nNo need to be picky: human, orc... it doesn't matter. Parts is parts.\n\nJust be sure the corpses you harvest come from the Battlescar, so I know they're fresh.\n\n<Calder presses a rusted, gore-covered bonesaw into your hands and smiles disarmingly.>", sourceObjective = "Use Calder's Bonesaw on corpses within the Battlescar and collect 15 Severed Extremities.", progress = "Did you get my parts? Let me see them!", completion = "<Calder peers into the sack of extremities and licks his lips with a dry, black tongue.>\n\nOh my. This is exciting.\n\n Aren't you excited, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24620] = { id = 24620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hearts-is-Hearts", description = "These parts - so lovely! Muscle and sinew and fingers and toes ... I am SO hungry right now.\n\nBut work must come first. Once I stitch this pile of parts together I'm going to need a heart strong enough to pump sludge through this rat's nest of veins. I would use my own heart, but it's a shriveled up husk resembling a turnip.\n\nNo, I need some real power. Get me a kodo heart from one of those giant landquaker bulls to the south of the Battlescar.", sourceObjective = "Slay a Landquaker Bull south of the Battlescar and collect an Enormous Kodo Heart.", progress = "You've gotta have heart, {name}. All you really need is heart.", completion = "<Calder grasps the gigantic heart in both hands, squeezing it and listening to the valves slurp and squish.>\n\n<His pale mask of a face splits open into an enormous, childlike grin.>\n\nIt is so very important to love one's work, wouldn't you agree, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24621] = { id = 24621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smarts-is-Smarts", description = "My monstrosity is taking shape! All that's left is to stuff his skull with something useful.\n\nI'm talking about brains, {name}. And here I'm going to be picky. The abomification process causes significant brain damage so it's best to start with someone smart.\n\nOne of the Alliance officers should do nicely. Seek out one of the Captains on the far side of the Battlescar and try not to damage the goods while you kill him.", sourceObjective = "Kill a Triumph Captain on the far side of the Battlescar and acquire a Fresh Brain.", progress = "Brraaaaaaiiinnnnss...", completion = "<Calder holds the brains in an outstretched hand while withdrawing a gore-caked multi-tool from his belt.>\n\nWonderful work! Now the secret here is to leave the reptilian nervous systems intact while removing the higher cognitive functions. We can't have our new friend developing a conscience or remembering he's Alliance...\n\n<Calder digs and snips at the brain, removing large chunks.>\n\nAnd... we're finished! How lovely.", sourceObjectiveStatus = "unverified-source-field" }
quests[24622] = { id = 24622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Troll's Truest Companion", description = "If ya lookin' for something ta do, we need some more raptors moved over to da pens. If ya head over to da island south of here, you can be meetin' with our caretakers and dey can set ya up.\n\nDey might appreciate a hand too. Got ta be spreadin' da love, ya know?", sourceObjective = "Speak to Kijara on Bloodtalon Shore.", completion = "Nice ta see new faces 'round here, mon. It's easy ta get ta feelin' isolated since we left Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24623] = { id = 24623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Young", description = "I actually have somethin' really important dat I could use help with, if ya be willin', mon.\n\nOur hatchlins' are bein' stolen by someone on da next island. At first I thought dey were just runnin' away or that nature be claimin' dem, but we are missin' more than a dozen of da little guys now.\n\nPlease head to Zalazane's Fall to da northwest and point da little hatchlins back dis way. Poor tings.", sourceObjective = "Use the Bloodtalon Whistle to rescue 12 Lost Bloodtalon Hatchlings.", completion = "Thank ya so much! They can be vicious when provoked, but most of da time dey don't know betta.", sourceObjectiveStatus = "unverified-source-field" }
quests[24624] = { id = 24624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mercy for the Lost", description = "The fiend who stole our raptors has been corruptin' dem with some kind of magic. Now dat dey've grown with dis corruption inside of them, I fear dere's little we can be doin' to save dem outside grantin' them da peace of death. Go ta Zalazane's Fall, northwest of here, an' see da task done.\n\nI hope ya can stomach dae work. I don't tink I could bring myself ta do da deed, even knowin' that it be needed.", sourceObjective = "Kill 8 Corrupted Bloodtalon Raptors.", completion = "Thank you, {class}.\n\nIt will be takin' brave and determined people like you ta drive da Darkspear up again. I hope dere are more people even half as dedicated to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[24625] = { id = 24625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consort of the Sea Witch", description = "I been investigatin' our corrupted Bloodtalons troubles and I think I've found da source. A lone naga. He was holdin' a red orb aloft over our hatchlings and I could see dem... changin'.\n\nI'm certain he tinks his thievery and spellcastin' have gone unnoticed, so ya should be able ta catch him unawares. Kill dis naga and bring me back dat vile orb - you'll be findin' him to da northwest, at Zalazane's Fall.", sourceObjective = "Kill Naj'tess and retrieve his orb.", progress = "Da naga have been our enemies for a long, long time, and our previous encounters with dem have not gone well. It be clear dat dis time will be different. Tings have changed, and you be part of dat change.", completion = "Well done, {name}! Dis naga has set us back quite some time, but nothin' will be holdin' us down foreva.\n\nIt's good ta be havin' ya wit us, {name}. Ya have a fierce heart within ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24626] = { id = 24626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Young and Vicious", description = "Ya be a good one, {name}.\n\nMoraya was askin' for new raptors ta train. We shouldn't keep her waitin' any longa! I have a few other recruits bringin' some over as well, but I have a special one dat I've been promisin' Moraya for a while.\n\nSwiftclaw be one of our fastest and bravest young raptors yet, but he can be a bit unruly. I'll lend ya da lasso, I just need ya to catch him somewhere on da island here and steer him over to da pens on da main isle. I doubt he'll be makin' it easy on ya though.", sourceObjective = "Capture Swiftclaw and bring him back to the pens near Darkspear Hold.", completion = "Swiftclaw! Kijara was tellin' me about him and he sounded like he'd be a handful. I don't mind da challenge - it's da spirited ones like dat that be makin' da bravest and truest companions when real times of need be comin'.\n\nTank ya, hon. Ya've been very helpful.", sourceObjectiveStatus = "unverified-source-field" }
quests[24627] = { id = 24627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At Our Doorstep", description = "The night elves have taught us much during this time, {name}.  They've taught us who we are and where we come from.\n\nThanks to them... thanks to this place... we're no longer mere beasts.  We have regained free will.\n\nThe Forsaken aren't here for our land alone.\n\nThey're looking for something we possess.  An artifact capable of uncontrollably spreading the Curse to all humanity.  We cannot let them find it.\n\nSylvanas's banshees have come very close.  Help my trackers take them out.", sourceObjective = "Kill 6 Howling Banshees.", progress = "You're back, {name}.", completion = "You are as good as I remember, {name}.  It is good to have you back.", sourceObjectiveStatus = "unverified-source-field" }
quests[24628] = { id = 24628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations", description = "What you know as the Curse began as a heresy among our brethren.\n\nFaced with a losing battle against demonic forces, the Druids of the Pack eschewed the balance they were sworn to and allowed the beast to overtake them.\n\nThey were banished to the Emerald Dream where they live in eternal slumber under a tree identical to this one, but not before their curse spread to others.\n\nToday our ceremony will restore balance to your people. Bring me the leaf that grows only in Tal'doren's vicinity.", sourceObjective = "Bring 6 Moonleafs to Vassandra.", progress = "You've returned, {name}.", completion = "These simple leaves grow by Elune's grace.  They will help your mind understand the need for balance and your soul will permanently earn mastery over the beast.", sourceObjectiveStatus = "unverified-source-field" }
quests[24629] = { id = 24629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Puff of Perfume", description = "You look like a real go-getter, {class}. How about we work out a little win-win scenario?\n\nCrown's looking to offer samples of our latest holiday-themed products to as many potential customers as possible. Help us share the love, and we'll give you discounts on some great Crown merchandise!\n\nYour time, our money, friend. What do you say?", sourceObjective = "Spray 10 people with the Crown Perfume Sprayer.", completion = "Great work, {name}! People will come running to buy Crown perfumes now that they've had a chance to sample their wonders.\n\nHere's a little something for helping us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[24631] = { id = 24631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flightmare", description = "The Alliance has hired in Wildhammer mercenaries to control the skies over the Battlescar. I believe these same gryphon-riders were the ones to firebomb Taurajo during the attack.\n\nI want our skies scoured clean.\n\nThe wildhammer dwarves fly low enough for a sharp-eyed {class} to hook them. Take this. Target their gryphons and dismount the riders - once grounded, show them no mercy.", sourceObjective = "Use Tomusa's Hook on Triumph War Gryphons to dismount and kill 5 Wildhammer Mercenaries.", progress = "The Wildhammer are fierce fighters, in the air or on the ground. How goes the battle?", completion = "<Tomusa snorts as he takes back his hook.>\n\nVengeance feels hollow. Still. I could not allow them to go unpunished.", sourceObjectiveStatus = "unverified-source-field" }
quests[24632] = { id = 24632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauren Vengeance", description = "My people are not wrathful by nature, but sometimes a thirst for justice causes us to take up arms in anger.\n\nMy old friend Gann Stonespire, on learning of the butchery in Taurajo, flew into a fury. Tribal elders could no longer hold his rage in check.\n\nNow he has all but parted ways with the Horde. He's gone rogue, {name}, and seeks to lash out at the Alliance with a small band of like-minded partisans.\n\nIf you, too, seek vengeance, you will find him southeast of here, at the foot of Bael Modan.", sourceObjective = "Seek out Gann Stonespire at Spearhead in Southern Barrens.", completion = "<Gann looks you up and down.>\n\nWe could use your help, {class}. But this is not a skirmish. We fight here to strike a killing blow... or die trying.", sourceObjectiveStatus = "unverified-source-field" }
quests[24633] = { id = 24633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mahka's Plea", description = "I can't put him out of my mind, {name}. Sometimes at night, I can hear his howls of rage and suffering, echoing across the plains. To imagine him out there, alone and in such pain...\n\nPlease, I must ask a favor of you. Go to Mankrik, and tell him to come see me.", sourceObjective = "Talk to Mankrik.", progress = "I am sorry to ask this of you, but I want him to come here. He needs to leave that place of death...", completion = "Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24634] = { id = 24634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intelligence Warfare", description = "I am convinced the Alliance is using spies to scout the field and pass along information. They knew to strike at Taurajo while the hunters were afield. And they countered every one of Gar'dul's moves like he was an open book.\n\nWell {name}, I for one will not be outplayed. Not here. We will win the battle for intelligence.\n\nEven now I hear reports of Alliance operatives slinking around in the shadows, especially here, outside these very walls. Kill them and bring me back something of use.", sourceObjective = "Kill a Barrens Operative and retrieve the SI:7 Briefings.", progress = "Watch your back, {class}. They could be anywhere.", completion = "Hah! The fool didn't destroy these orders.\n\nLet's see what we can learn...", sourceObjectiveStatus = "unverified-source-field" }
quests[24635] = { id = 24635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cloudlet of Classy Cologne", description = "You seem the enterprising sort, {class}. How about we make a little deal?\n\nCrown wants to offer samples of our latest holiday-themed products to as many potential customers as we can. Help us share the love while earning some fantastic Crown merchandise!\n\nYour time, our money, friend. What do you think?", sourceObjective = "Spray 10 people with the Crown Cologne Sprayer.", progress = "That cologne isn't going to give itself out, you know.\n\nGet spraying!", completion = "Nice work, {name}! People will be buying Crown colognes by the crate-load now that they've had a chance to try them.\n\nHere's a little something for helping us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[24636] = { id = 24636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonbon Blitz", description = "I can see you've got an eye for opportunity, {class}. What do you say we make a little coin together?\n\nCrown needs to push samples of our latest holiday-themed products to every potential customer in the city. Help us share the love, and we'll share some of that amazing Crown merchandise with you!\n\nYour time, our money, friend. We got a deal?", sourceObjective = "Toss 10 people samples from the Crown Chocolate Sampler.", progress = "You know, those chocolates aren't going to fling themselves at people.\n\nYou need to get to work!", completion = "Lovely work, {name}! People will be tripping over one another to get Crown chocolates now that they've had a chance to taste those sweet, romantic treats.\n\nHere's a little something for helping us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[24637] = { id = 24637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Butcher of Taurajo", description = "This operative had orders to secure the roadways between the Alliance command and Fort Triumph. General Hawthorne is on the move.\n\n<Bloodhilt crumples the documents in his fist.>\n\nIt's HIM, {name}! Hawthorne - I spit the name - he is the one who ordered the assault on Taurajo! Now we know when and where to strike him down. Quickly, follow the road north of the Battlescar and meet up with my assassin Karthog. CRUSH Hawthorne and string his body up along the road!", sourceObjective = "Speak with Karthog, then lure out and assassinate General Hawthorne.", completion = "<Upon hearing the news, Bloodhilt snorts. His eyes gleam. He tips his head back and bellows a wet, cackling laugher that echoes between the blackened walls of Desolation hold and reverberates throughout the hills beyond.>\n\nSo it is done! The Butcher of Taurajo is felled at last. Cut down in the streets like a dog. Fitting.\n\nYou have done well, {name}. You've sowed fear into our enemies, and soon we will reap the harvest!", sourceObjectiveStatus = "unverified-source-field" }
quests[24638] = { id = 24638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's right outside Orgrimmar's gates, to the west! That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon just west of Orgrimmar's gates in Durotar, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24639] = { id = 24639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dat weapon you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", completion = "Not bad, mon. Ya have a natural flow to ya swings - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[24640] = { id = 24640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Warrior", description = "As ya get bettah' at fightin', you'll start to find new tings that ya nevah knew you could do.\n\nWanna see? Go, train up some, and learn someting new.\n\n'Den come back and ya can show me.", sourceObjective = "Reach level 3 to learn Charge. Practice using Charge against a Tiki Target.", progress = "Veteran warriors can control much of da battlefield simply with da strength of deir presence. Whether it be rallyin' other fighters beside ya to greater strength, demoralizin' ya enemies with da fierceness of ya attacks, our intimidatin' ya foes into runnin' from da very sight of ya, it's more than just the weapon dat makes da {class}.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24641] = { id = 24641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
quests[24642] = { id = 24642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", sourceObjective = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", sourceObjectiveStatus = "unverified-source-field" }
quests[24643] = { id = 24643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", sourceObjective = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", sourceObjectiveStatus = "unverified-source-field" }
quests[24645] = { id = 24645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just outside Ambermill in Silverpine Forest. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Thugs and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Ambermill in Silverpine Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24646] = { id = 24646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Back What's Ours", description = "Ever since the Forsaken invaded Gilneas, we've tried to keep the location of the Scythe of Elune secret.   We moved it at night to one of many safe locations.  The Dark Rangers got close, but never found it... until now.\n\nThey were last spotted at the Woods' End Cabin, west of here.  Blow this horn when you find them and Tobias and his trackers will engage the Dark Rangers.\n\nOnly then will it be safe for you to venture inside the cabin and take back the scythe.  Hurry, {name}.  It must not reach Sylvanas.", sourceObjective = "Blow the Horn of Tal'doren at the Woods' End Cabin and retrieve the Mysterious Artifact inside.", progress = "Do you have the scythe, {name}?", completion = "I knew we could count on you.  You've done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24647] = { id = 24647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just outside the village of Hillsbrad in -- you guessed it -- Hillsbrad Foothills. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Dusters and use Snagglebolt's Khorium Bomb to destroy one chemical wagon just outside of Hillsbrad Village in Hillsbrad Foothills, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24648] = { id = 24648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's near Sentry Point, just outside Theramore in Dustwallow. Don't give me that look, okay? This is a problem for us, too. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Hoodlums and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Theramore in Dustwallow Marsh, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24649] = { id = 24649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's to the east of Aerie Peak in the Hinterlands. Don't give me that look, okay? This is a problem for the Horde, too. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Agents and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Aerie Peak in the Hinterlands, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24650] = { id = 24650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's in Winterspring, just east of Everlook. Oh, now this is personal. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprinklers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Everlook in Winterspring, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24651] = { id = 24651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's just east of Shattrath, in Terokkar Forest. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Underlings and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Shattrath City in Terokkar Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24652] = { id = 24652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's in the Forlorn Woods of Crystalsong, northwest of the Mirror of Twilight. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprayers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon in the Forlorn Woods of Crystalsong Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", progress = "Did you teach 'em a lesson?", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24653] = { id = 24653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Agamaggan", description = "I think the quilboar are being driven by more than just crude desire. Would you help me look into this further?\n\nTo the west, scattered among the quilboar's settlements and camps, I've noticed boar skulls. They gleam from a distance, polished smooth...distinct from the remains littered in their waste piles. I think these may be objects of worship.\n\nBring me several of these to examine, {name}.", sourceObjective = "Collect 3 Polished Boar Skulls.", progress = "Do you have the skulls?", completion = "Yes, these are clearly symbols of Agamaggan. But if the quilboar are still devoted to their dead god, what is the source of their vicious agression?  It is said Agamaggan was noble, and even gave his life fighting the Burning Legion...\n\nA moment, {name}. We must confer with the spirits.", sourceObjectiveStatus = "unverified-source-field" }
quests[24654] = { id = 24654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silithissues", description = "The silithid! They're bugs, {name}. Or something like bugs. They're not natural... and we built a fortress on the equivalent of an anthill.\n\nTake this burning pitch. It'll set the buggers on fire and plug up their burrows at the same time. Be careful when you pour this stuff on there - the silithid will come out in swarms!\n\nLook for silithid mounds around the exterior of Desolation Hold. They look like heaps of sand. Kill anything that crawls out.", sourceObjective = "Use the Bucket of Burning Pitch on Silithid Mounds and kill 10 Silithid Swarmers as they emerge.", progress = "The Alliance is nothing. Swarms of those critter-crawlys?\n\n<Crawgol shudders.>", completion = "You're covered in hot tar and bug juice! Don't worry, friend. It'll come off.\n\nSomeday.", sourceObjectiveStatus = "unverified-source-field" }
quests[24655] = { id = 24655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Stinks", description = "Get a load of these guys, would ya? Steamwheedle's been handling the business of holidays for years, and all of a sudden, these guys bust into the market. They're not Steamwheedle; the cartel hired me to get to the bottom of this. Something stinks here and it ain't just perfume.\n\nTake this device I brought and go analyze the perfume clouds around the guards. I want to know what they're putting in that stuff. Things ain't natural.", sourceObjective = "Use Snagglebolt's Air Analyzer to test the air around 6 heavily perfumed guards, then return to Inspector Snip Snagglebolt in Stormwind.", progress = "You analyze that reek yet, kid?", completion = "Hey, thanks, kid. Give it over, let's take a look.\n\n<He takes the device from you and fiddles with it.>\n\nOh, that ain't good.", sourceObjectiveStatus = "unverified-source-field" }
quests[24656] = { id = 24656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfering Perfume", description = "I knew they were up to no good! There's some sort of mind-affecting chemical in here, but I can't get a handle on it with such a small sample. I need the real stuff.\n\nDon't just go over there and buy it! I don't want you giving these scumbags one copper. Nah, you gotta get it from the source, discreet-like.\n\nI'll disguise you as a package runner. I saw a stockpile guarded by their goons outside the gates. Go run by, and DON'T stop, or they'll make you! They'll toss you a crate. Bring it back here.", sourceObjective = "While disguised as a package-runner, go to the Crown Chemical Company's stockpile outside the gates of Stormwind, then return the package they toss you to Inspector Snip Snagglebolt in Stormwind.", progress = "Did they toss ya a crate to deliver?", completion = "You got it, huh? Good job, kid. Top notch. Let's see what we got here.\n\n<He cracks open the crate and rummages around inside.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24657] = { id = 24657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friendly Chat...", description = "<Marion listens with horror as you tell her why you're trying to track down Snivel.>\n\nYou mean, he might've used some kind of chemical on me? Ew! I can't believe I fell for that fraud!\n\nIf he's finished all of his errands, he's on his way down to the docks to catch a ship to the South Seas! Whatever you do, {name}, you can't let him get away with this.\n\nHurry down to Stormwind Harbor before you miss him!", sourceObjective = "Go to Stormwind Harbor and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.", progress = "Did you find the guy, or did he crawl under a rock?", completion = "You got his ledger? Really? That's great, {name}. There's probably loads of good information in here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24658] = { id = 24658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's northeast of Westbrook Garrison right outside in Elwynn! That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon northeast of Westbrook Garrison in Elwynn Forest, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24659] = { id = 24659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just south of the Grove of the Ancients in Darkshore. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Thugs and use Snagglebolt's Khorium Bomb to destroy one chemical wagon south of the Grove of the Ancients in Darkshore, then return to Inspector Snip Snagglebolt in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[24660] = { id = 24660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just southeast of Darkshire in Duskwood. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Dusters and use Snagglebolt's Khorium Bomb to destroy one chemical wagon at the abandoned farm southeast of Darkshire in Duskwood, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24661] = { id = 24661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's right outside Orgrimmar's gates, to the west! That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon just west of Orgrimmar's gates in Durotar, then return to Detective Snap Snagglebolt in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24662] = { id = 24662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's near Sentry Point, just outside Theramore in Dustwallow. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Hoodlums and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Theramore in Dustwallow Marsh, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24663] = { id = 24663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's to the east of Aerie Peak in the Hinterlands. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Agents and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Aerie Peak in the Hinterlands, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24664] = { id = 24664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's in Winterspring, just east of Everlook. Oh, now this is personal. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprinklers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Everlook in Winterspring, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24665] = { id = 24665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's just east of Shattrath, in Terokkar Forest. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Underlings and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Shattrath City in Terokkar Forest, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24666] = { id = 24666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's in the Forlorn Woods of Crystalsong, northwest of the Mirror of Twilight. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprayers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon in the Forlorn Woods of Crystalsong Forest, then return to Inspector Snip Snagglebolt in Stormwind.", progress = "Did you teach 'em a lesson?", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24667] = { id = 24667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firestone Point", description = "I've been on top of this silithid situation for almost a month, which makes me the local expert. Just last week the Earthen Ring was visiting, and wanted me to write down everything I know.\n\n<Crawgol hands you a tattered book.>\n\nI'm not much of a writer. Or a reader, for that matter. But this book is probably the most definitive thing ever written about this foe.\n\nDeliver it to Tauna Skychaser down in Firestone Point. It's south of here, just west of the main road.", sourceObjective = "Deliver Crawgol's Silithid Field Guide to Tauna Skychaser at Firestone Point in Southern Barrens.", progress = "Ah, do you bring news from up north?", completion = "Is this from Crawgol? Wonderful! Despite all the turmoil in the world, we can't turn our back on the silithid threat. It is important to have people like Crawgol studying our enemy closely and learning its secrets for the fight ahead!\n\n<Tauna opens the book and glances over the first page. Her face falls.>\n\nOh. Well. I suppose it's something, at least.", sourceObjectiveStatus = "unverified-source-field" }
quests[24671] = { id = 24671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cluster Cluck", description = "Ridiculous! The greatest goblin mind of all time reduced to food detail? I made the Micro Mechachicken just for this reason and they let it get away!\n\n<Hobart turns a deeper shade of green as his blood pressure rises.>\n\nDo I look like I should be rounding up escaped cluckers? No, my friend, not I! Bamm most definitely, though he's too lazy.\n\nYour station in life has recently taken a turn for the worse. You do it!\n\nTake these remote control fireworks and attach them to the cluckers.", sourceObjective = "Capture 10 Wild Cluckers by attaching remote control fireworks to them.", progress = "Not enough cluckers, {name}. We'll all starve.", completion = "Success! Was there ever any doubt?\n\nGreely, fire up the poultryizer!", sourceObjectiveStatus = "unverified-source-field" }
quests[24672] = { id = 24672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onwards and Upwards", description = "I will do as Darius asked and have our people move through the Blackwald.\n\nYou ought to catch up with King Greymane.  He and Krennan went into Tempest's Reach after Lord Godfrey confirmed survivors had made their dwelling there.\n\nFollow the road out of Stormglen into the mountains.  I asked Krennan to wait for you at the bridge before Tempest's Reach.", sourceObjective = "Find Krennan Aranas on the road to Tempest's Reach.", completion = "{name}!\n\nGenn... they've taken Genn... they've taken... our king!", sourceObjectiveStatus = "unverified-source-field" }
quests[24673] = { id = 24673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Stormglen", description = "It'll be a long time before our nation comes together again.  The old political divisions pale in comparison to what divides us now.\n\nYet if there was ever a time for us to come together and unite against a common enemy, it is now.  And it is you, {name}, who have proven able to bridge the gap between our people.\n\nReturn to Stormglen and tell them it is safe to go through the Blackwald on their way to Tempest's Reach.  We will take care of any Forsaken who follow them.", sourceObjective = "Speak to Gwen Armstead in Stormglen.", completion = "King Greymane gave me a brief rundown of the plan before he set off for the Blackwald.  Doesn't make it sound any less crazy.", sourceObjectiveStatus = "unverified-source-field" }
quests[24674] = { id = 24674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves to No One", description = "I was one of the few that escaped, {name}.  When the Forsaken took over our town and our mine, they treated us with utmost cruelty.\n\nThose of us who were weak and could not endure hard labor were worked to death by the abomination known as Brothogg.\n\nMy wife was among his victims, {class}, and I swore that one day her death would be avenged.  I am too frail now, but you can deliver justice... for my wife... for Gilneas!", sourceObjective = "Slay Brothogg the Slavedriver inside Emberstone Mine.", progress = "Is it done?", completion = "I thank you, {name}.  Our people will no longer suffer under that monstrosity's yoke.", sourceObjectiveStatus = "unverified-source-field" }
quests[24675] = { id = 24675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Meal", description = "I'm not dumb, {name}.  I know what's ahead of us.\n\nOur people are going to go through those gates and fight against an enemy that is better trained, has more numbers and better weapons than us.\n\nEven if we succeed, it'll be at a great cost.  For most of us, today's meal will be the last.\n\nI cannot fight, but I sure can cook.  Bring me meat from the stags that roam this area and I will ensure that the last meal these folks get will be their best.", sourceObjective = "Obtain 10 Sides of Stag Meat.", progress = "Did you get what I needed, {name}?", completion = "I thank you, {name}.  Our men and women will have a last good meal before they set off for battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[24676] = { id = 24676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Push Them Out", description = "The people are free, but the town is still occupied by the Forsaken.  They're cut off from their main force, so if we're to drive them out, now's our chance.\n\nTheir leader, Executor Cornell, is known  for his unbound ruthlessness.  Also among them is Valnov the Mad, a so-called scientist who carries out inhuman experiments on villagers too old to work the mines.\n\nTake care of them all.", sourceObjective = "Slay 4 Forsaken Infantry, Executor Cornell and Valnov the Mad in Emberstone Village.", progress = "You're back, {name}.", completion = "We have the people of Emberstone on our side now thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24677] = { id = 24677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flank the Forsaken", description = "I thank you, {name}.  We can't rest on our laurels, however.\n\nWe found out about a mining town, currently under Forsaken occupation.  We sent some of my men, along with Crowley's daughter to the nearby livery stables to begin operations there.  Liam should be joining them shortly.\n\nI'll stay here and organize the final push for Gilneas City.  Speak to Lord Hewell to secure a horse to get you there.", sourceObjective = "Speak to Lord Hewell to obtain a ride to the Livery Outpost and report to Lorna Crowley.", completion = "I am glad to have you here, {name}.  We're surrounded by Forsaken on all sides and can use all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[24678] = { id = 24678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knee-Deep", description = "It's time to pack it in, {name}.  Most of our people have made it through -- it's your turn now.\n\nTake this torch, you're going to need it.  The tunnel is full of nasty, knee-biting critters of the worst kind.  Use it to keep them at bay.\n\nSpeak to Krennan on the other side.", sourceObjective = "Use the Half-Burnt Torch to get to the other side of the tunnel beneath Gilneas City.\n\nProvided item:", completion = "You're here, {name}.  Most everyone made it through, but now we're stuck here... surrounded by our own... dead!", sourceObjectiveStatus = "unverified-source-field" }
quests[24679] = { id = 24679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patriarch's Blessing", description = "You've done it, {name}.  Even in these times we must honor our dead.\n\nTake these offerings and place them at Aderic's tomb.\n\nLet's hope that's enough to placate the ghosts of our ancestors.", sourceObjective = "Place the Blessed Offerings at Aderic's Tomb.", progress = "Is it done, {name}?", completion = "It's done, {name}.  The dead return to their slumber.", sourceObjectiveStatus = "unverified-source-field" }
quests[24680] = { id = 24680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keel Harbor", description = "We might've lost our city, but at least it looks like the dead have forgiven us.\n\nMeet with the rest of the survivors in Keel Harbor.\n\nI'm sure there's plenty to do before we're in the clear.  Genn hasn't arrived yet, so I suppose Lord Crowley will be in charge there.", sourceObjective = "Speak to Lord Darius Crowley at Keel Harbor in Gilneas.", completion = "It's good to see you again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24681] = { id = 24681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Have Allies, But So Do We", description = "The night elves made good on their promise.  They've brought ships and are ready to offer us sanctuary in their lands.\n\nUnfortunately, the Forsaken's allies have arrived as well.\n\nThe orcs are advancing upon us while the Horde gunship prevents the transport ships from taking our people to safety.\n\nThe druids are holding the enemy back, but won't last long.  Fortunately, the elven ships were carrying siege weapons.  Take one of the glaive throwers and meet the enemy head on.", sourceObjective = "Use the Night Elven Glaivethrower to slay 40 Orc Raiders, 8 Wolfmaw Outriders and 4 Orcish War Machines.", progress = "You're back!", completion = "It's almost over, {name}.  Only one obstacle remains between us and survival.", sourceObjectiveStatus = "unverified-source-field" }
quests[24682] = { id = 24682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pit of Saron", description = "Quickly, through the portal! I'll find you on the other side.", sourceObjective = "Meet Lady Sylvanas Windrunner inside the entrance to the Pit of Saron.", completion = "Incapable fools. I begin to wonder if any of these louts from the tournament will be of any use at all. Perhaps you'll prove me wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[24683] = { id = 24683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pit of Saron", description = "Quickly, through the portal! I'll meet you on the other side.", sourceObjective = "Meet Lady Jaina Proudmoore just inside the Pit of Saron.", completion = "I underestimated this Scourgelord, and it's my men that paid for it. When I think that my guilt over Arthas' betrayal cannot go any deeper, he proves me wrong yet again.\n\nWe have to press on. We cannot let their sacrifice be meaningless.", sourceObjectiveStatus = "unverified-source-field" }
quests[24684] = { id = 24684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Weezil in the Henhouse", description = "<Gann grasps you with a blood-caked hand.>\n\nMy wounds are great but I will not rest until the dwarves of Bael Modan pay for their crimes. <Wheeze> We smuggled a man inside their fortress during our last raid. A goblin saboteur: Weezil Slipshadow. \n\nCreate a disruption at the gates - kill who you can - then slip inside the fortress of Bael'dun to the south and find Weezil.\n\nThat stronghold <cough> can only be destroyed from within, and Weezil can't do it alone.", sourceObjective = "Head into the Bael'Dun Keep and kill 10 Bael'Dun Dwarves (Riflemen, Soldiers, and Officers.) Then find Weezil Slipshadow, who should be hiding within.", progress = "Quiet, you big plodding brute! Keep your voice down.\n\nIf they spot us talking, pretend I'm just ordinary cheese.", completion = "You do good work, {class}. That riot you caused at the fortress entrance has these dwarves running around with their heads cut off.", sourceObjectiveStatus = "unverified-source-field" }
quests[24685] = { id = 24685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dwarf Fortress", description = "I don't know if you noticed on your way in, but this whole fortress is erected around a giant cannon. If we can just find the ammunition magazine, we could blow this place sky-high as easy as kiss-my-hand!\n\nBut to figure it out I'm going to need the fortress schematics, and I haven't been able to steal them yet.\n\nLook for the plans on the lowest floor, right down these stairs.", sourceObjective = "Acquire the Bael'Dun Fortress Schematics.", progress = "Give me the plans, quickly! Our time grows short.\n\nMostly because I've been eating my disguise.", completion = "Let's see, let's see.\n\nIt looks like the artillery shells are prepped here, then loaded into the secure magazine...\n\n<Weezil rubs his hands together.>\n\n{name}, are you ready to blow some stuff up?", sourceObjectiveStatus = "unverified-source-field" }
quests[24686] = { id = 24686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carried on the Waves", description = "The Bloodpetals of Un'Goro have a fascinating life cycle.\n\nThese trees in front of us bear seeds that fall down into the river when they mature.  The river's current then takes the seed north of here, where the seed hatches - almost like an egg - and a newborn Bloodpetal emerges.\n\nI require these seeds for my studies.  Take this net, and use it to scoop up the bright orange seeds in the river.  You'll have to hunt them down under the water.", sourceObjective = "Use Garl's Net to obtain 4 Bloodpetal Seeds.", progress = "Have you obtained the seeds yet?", completion = "Hmm... yes, these seeds will do nicely.  You have the gratitude of the Cenarion Circle, {name}.", sourceObjectiveStatus = "unverified-source-field" }
